const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:36,000", "arabic": "أَجَلْ يَا أُمَّ أَحْمَدَ، أُرِيدُكِ لَوْ لَا أَنْ يَشُقَّ عَلَيْكِ أَنْ تُحَضِّرِي وَلِيمَةً تَلِيقُ بِرَجُلٍ مِنَ السَّادَةِ", "segs": [{"ar": "أَجَلْ يَا أُمَّ أَحْمَدَ، أُرِيدُكِ لَوْ لَا أَنْ يَشُقَّ عَلَيْكِ", "uz": "Ha, ey Ahmadning onasi — agar sizga og'ir bo'lmasa"}, {"ar": "أَنْ تُحَضِّرِي وَلِيمَةً تَلِيقُ بِرَجُلٍ مِنَ السَّادَةِ", "uz": "sayyidlardan biriga munosib bir ziyofat tayyorlashingizni istardim"}], "full_uz": "Ha, ey Ahmadning onasi — agar sizga og'ir bo'lmasa, sayyidlardan biriga munosib bir ziyofat tayyorlashingizni istardim.", "note": null},
  {"num": 3, "time": "00:00:37,000 --> 00:00:42,000", "arabic": "رَجُلٌ مِنَ السَّادَةِ؟ مَنْ هُوَ؟ ثُمَّ مِنْ أَيْنَ لَكَ النُّقُودُ؟", "segs": [{"ar": "رَجُلٌ مِنَ السَّادَةِ؟ مَنْ هُوَ؟", "uz": "Sayyidlardan biri? Kim ekan?"}, {"ar": "ثُمَّ مِنْ أَيْنَ لَكَ النُّقُودُ؟", "uz": "Yana, senda pul qayerdan bor?"}], "full_uz": "Sayyidlardan biri? Kim ekan? Yana, senda pul qayerdan bor?", "note": null},
  {"num": 4, "time": "00:00:43,000 --> 00:00:48,000", "arabic": "أَمَّا مَنْ هُوَ يَا أُمَّهْ، فَهُوَ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ الْهَاشِمِيُّ", "segs": null, "full_uz": "Kim ekaniga kelsak, onajon, u — Muhammad ibn Idris ash-Shofi'iy al-Hoshimiy.", "note": null},
  {"num": 5, "time": "00:00:49,000 --> 00:00:52,000", "arabic": "أَمَّا مِنْ أَيْنَ لِيَ النُّقُودُ، فَهِيَ مِنَ اللَّهِ عَزَّ وَجَلَّ", "segs": null, "full_uz": "Pulga kelsak esa, u Alloh azza va jalladandir.", "note": null},
  {"num": 6, "time": "00:00:53,000 --> 00:00:58,100", "arabic": "اَلْحَمْدُ لِلَّهِ، اَلْحَمْدُ لِلَّهِ عَلَى اللَّهِ، اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Alhamdulillah, alhamdulillah, alhamdulillah.", "note": null},
  {"num": 8, "time": "00:00:58,100 --> 00:01:02,000", "arabic": "اَلْحَمْدُ لِلَّهِ عَلَى نِعَمٍ حَسَنٍ يَا وَلَدِي", "segs": null, "full_uz": "Yaxshi ne'matlar uchun alhamdulillah, o'g'lim.", "note": null},
  {"num": 9, "time": "00:01:02,000 --> 00:01:08,159", "arabic": "فَقَالَ لِي قَائِلٌ", "segs": null, "full_uz": "Menga bir kishi dedi.", "note": null},
  {"num": 10, "time": "00:01:08,159 --> 00:01:16,700", "arabic": "حَدِّدْ لِي أَقَلَّ مَا تَقُومُ بِهِ الْحُجَّةُ عَلَى أَهْلِ الْعِلْمِ حَتَّى يَثْبُتَ عَلَيْهِمْ خَبَرُ خَاصَّةٍ", "segs": null, "full_uz": "Menga aniqlab bergin — ilm ahli uchun hujjat qay darajada bo'lganda, xos xabar ular uchun sobit bo'ladi.", "note": null},
  {"num": 12, "time": "00:01:16,700 --> 00:01:21,099", "arabic": "فَقُلْتُ خَبَرُ الْوَاحِدِ عَنِ الْوَاحِدِ", "segs": null, "full_uz": "Men dedim: bittadan-bittaga yetib kelgan xabar bilan.", "note": null},
  {"num": 13, "time": "00:01:21,099 --> 00:01:31,640", "arabic": "حَتَّى يَنْتَهِيَ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ مَنِ انْتَهَى بِهِ إِلَيْهِ دُونَهُ", "segs": null, "full_uz": "Toki u Payg'ambar sollallohu alayhi va sallamgacha yetib borsin, yoki undan pastroq kishigacha yetib borsin.", "note": null},
  {"num": 15, "time": "00:01:31,640 --> 00:01:37,439", "arabic": "وَلَا تَقُومُ الْحُجَّةُ بِخَبَرِ خَاصَّةٍ حَتَّى تُجْمَعَ أُمُورًا مِنْهَا", "segs": null, "full_uz": "Xos xabar bilan hujjat sobit bo'lmaydi, toki bir necha shart jam bo'lmaguncha.", "note": null},
  {"num": 16, "time": "00:01:37,439 --> 00:01:48,639", "arabic": "أَنْ يَكُونَ مَنْ حَدَّثَ بِهِ ثِقَةً صَادِقًا عَاقِلًا عَالِمًا بِمَا يُحِيلُ مَعَانِيَ الْحَدِيثِ مِنَ اللَّفْظِ", "segs": null, "full_uz": "Uni rivoyat qiluvchi ishonchli, rostgo'y, aqlli, va lafzdan hadis ma'nolarini o'zgartiruvchi narsalarni biladigan bo'lishi kerak.", "note": null},
  {"num": 17, "time": "00:01:48,640 --> 00:01:57,640", "arabic": "وَأَنْ يَكُونَ مِمَّنْ يُؤَدِّي الْحَدِيثَ بِحُرُوفِهِ كَمَا سَمِعَهُ، وَلَا يُحَدِّثُ بِهِ عَلَى الْمَعْنَى", "segs": [{"ar": "وَأَنْ يَكُونَ مِمَّنْ يُؤَدِّي الْحَدِيثَ بِحُرُوفِهِ كَمَا سَمِعَهُ", "uz": "Va hadisni eshitgan harflari bilan aynan yetkazuvchi bo'lishi kerak"}, {"ar": "وَلَا يُحَدِّثُ بِهِ عَلَى الْمَعْنَى", "uz": "ma'no bo'yicha rivoyat qilmasligi kerak"}], "full_uz": "Va hadisni eshitgan harflari bilan aynan yetkazuvchi bo'lishi, ma'no bo'yicha rivoyat qilmasligi kerak.", "note": null},
  {"num": 19, "time": "00:01:57,640 --> 00:02:11,139", "arabic": "لِأَنَّهُ إِذَا حَدَّثَ بِهِ عَلَى الْمَعْنَى وَهُوَ غَيْرُ عَالِمٍ بِمَا يُحِيلُهُ مَعْنًى لَمْ يَدْرِ لَعَلَّهُ يُحِيلُ الْحَلَالَ إِلَى حَرَامٍ", "segs": [{"ar": "لِأَنَّهُ إِذَا حَدَّثَ بِهِ عَلَى الْمَعْنَى وَهُوَ غَيْرُ عَالِمٍ بِمَا يُحِيلُهُ مَعْنًى", "uz": "Chunki agar u ma'no bo'yicha rivoyat qilsa-yu, ma'noni o'zgartiruvchi narsani bilmasa"}, {"ar": "لَمْ يَدْرِ لَعَلَّهُ يُحِيلُ الْحَلَالَ إِلَى حَرَامٍ", "uz": "balki halolni haromga aylantirib qo'yishini sezmay qoladi"}], "full_uz": "Chunki agar u ma'no bo'yicha rivoyat qilsa-yu, ma'noni o'zgartiruvchi narsani bilmasa, balki halolni haromga aylantirib qo'yishini sezmay qoladi.", "note": "Bu — Imom ash-Shofi'iyning hadis rivoyat qilish shartlari haqidagi mashhur so'zlaridan."},
  {"num": 22, "time": "00:02:11,139 --> 00:02:18,180", "arabic": "مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ أَفْقَهُ رَجُلٍ لَقِيتُ مُنْذُ أَنْ خَرَجْتُ إِلَى طَلَبِ حَدِيثِ رَسُولِ اللَّهِ", "segs": null, "full_uz": "Muhammad ibn Idris ash-Shofi'iy — Rasululloh hadisini izlab chiqqanimdan beri uchratgan eng fақih odamim.", "note": null},
  {"num": 24, "time": "00:02:18,180 --> 00:02:25,319", "arabic": "إِنَّهُ مِنْ أَنْبَهِ طُلَّابِ الْإِمَامِ مَالِكِ بْنِ أَنَسٍ رَحِمَهُ اللَّهُ، فَلَقَدْ تَصَدَّرَ لِلتَّدْرِيسِ فِي الْخَامِسَةَ عَشْرَةَ مِنْ عُمُرِهِ", "segs": [{"ar": "إِنَّهُ مِنْ أَنْبَهِ طُلَّابِ الْإِمَامِ مَالِكِ بْنِ أَنَسٍ رَحِمَهُ اللَّهُ", "uz": "U Imom Molik ibn Anasning — Alloh unga rahmat qilsin — eng ko'zga ko'ringan talabalaridandir"}, {"ar": "فَلَقَدْ تَصَدَّرَ لِلتَّدْرِيسِ فِي الْخَامِسَةَ عَشْرَةَ مِنْ عُمُرِهِ", "uz": "U o'n besh yoshida dars berishga boshchilik qilgan"}], "full_uz": "U Imom Molik ibn Anasning — Alloh unga rahmat qilsin — eng ko'zga ko'ringan talabalaridandir — u o'n besh yoshida dars berishga boshchilik qilgan.", "note": null},
  {"num": 26, "time": "00:02:25,319 --> 00:02:30,460", "arabic": "إِنَّهُ عَالِمٌ يَا أُمَّاهُ قَلَّ أَنْ نَجِدَ نِدًّا لَهُ", "segs": null, "full_uz": "U shunday olimki, onajon, tengini topish qiyin.", "note": null},
  {"num": 27, "time": "00:02:30,460 --> 00:02:38,260", "arabic": "لَمْ أَرَكَ مِنْ قَبْلُ تَتَحَدَّثُ عَنْ رَجُلٍ بِمِثْلِ هَذَا الْإِعْجَابِ يَا بُنَيَّ", "segs": null, "full_uz": "Ilgari sen biror kishi haqida bunday hayrat bilan gapirganingni ko'rmagandim, o'g'lim.", "note": null},
  {"num": 29, "time": "00:02:38,260 --> 00:02:44,200", "arabic": "ذَلِكَ أَنِّي لَمْ أَرَ قَبْلَ الشَّافِعِيِّ رَجُلًا يَمْلَأُ النَّفْسَ رُوحًا وَعَقْلًا وَسَمْعًا وَبَصَرًا", "segs": null, "full_uz": "Chunki ash-Shofi'iydan oldin ruh, aql, quloq va ko'zni to'ldiradigan bir kishini ko'rmagandim.", "note": null},
  {"num": 31, "time": "00:02:44,200 --> 00:02:47,800", "arabic": "بَارِعٌ فِي الْحَدِيثِ، عَالِمٌ فِي اللُّغَةِ، مُتَمَكِّنٌ فِي الْفِقْهِ", "segs": [{"ar": "بَارِعٌ فِي الْحَدِيثِ", "uz": "Hadisda mohir"}, {"ar": "عَالِمٌ فِي اللُّغَةِ", "uz": "tilda olim"}, {"ar": "مُتَمَكِّنٌ فِي الْفِقْهِ", "uz": "fiqhda pishiq"}], "full_uz": "Hadisda mohir, tilda olim, fiqhda pishiq.", "note": null},
  {"num": 33, "time": "00:02:47,800 --> 00:02:57,840", "arabic": "يَبْدُو أَنَّ هَذَا الشَّافِعِيَّ قَدِ اسْتَأْثَرَ بِقَلْبِكَ يَا بُنَيَّ، وَقَدْ أَحْسَنْتَ صُنْعًا حِينَ أَرَدْتَ أَنْ تُوَلِّيَهُ", "segs": [{"ar": "يَبْدُو أَنَّ هَذَا الشَّافِعِيَّ قَدِ اسْتَأْثَرَ بِقَلْبِكَ يَا بُنَيَّ", "uz": "Bu Shofi'iy qalbingni to'liq egallaganga o'xshaydi, o'g'lim"}, {"ar": "وَقَدْ أَحْسَنْتَ صُنْعًا حِينَ أَرَدْتَ أَنْ تُوَلِّيَهُ", "uz": "unga bunday e'tibor bermoqchi bo'lganing yaxshi ish bo'lgan"}], "full_uz": "Bu Shofi'iy qalbingni to'liq egallaganga o'xshaydi, o'g'lim — unga bunday e'tibor bermoqchi bo'lganing yaxshi ish bo'lgan.", "note": null},
  {"num": 35, "time": "00:02:57,840 --> 00:03:04,640", "arabic": "فَإِكْرَامُ أَهْلِ الْعِلْمِ مِنْ حُسْنِ الْأَدَبِ يَا بُنَيَّ، أَجَلْ وَاللَّهِ يَا أُمِّي", "segs": null, "full_uz": "Ilm ahlini hurmatlash — yaxshi odob belgisidir, o'g'lim. Ha, Alloh haqi, onajon.", "note": null},
  {"num": 37, "time": "00:03:04,640 --> 00:03:14,520", "arabic": "إِنَّمَا تَسْتَحِقُّ أُذُنُ مَوْلَايَ أَنْ تَسْمَعَ سَيَكُونُ بَيْنَ يَدَيْهِ قَبْلَ أَنْ يَتَفَوَّهَ بِهِ صَاحِبُهُ فَكُنْ عَلَى ثِقَةٍ مِنْ ذَلِكَ يَا مَوْلَايَ", "segs": [{"ar": "إِنَّمَا تَسْتَحِقُّ أُذُنُ مَوْلَايَ أَنْ تَسْمَعَ", "uz": "Xo'jayinimning qulog'i eshitishga loyiq bo'lgani"}, {"ar": "سَيَكُونُ بَيْنَ يَدَيْهِ قَبْلَ أَنْ يَتَفَوَّهَ بِهِ صَاحِبُهُ", "uz": "egasi og'ziga olib ulgurmasidan oldin uning qo'lida bo'ladi"}, {"ar": "فَكُنْ عَلَى ثِقَةٍ مِنْ ذَلِكَ يَا مَوْلَايَ", "uz": "bunga ishonchingiz komil bo'lsin, xo'jayinim"}], "full_uz": "Xo'jayinimning qulog'i eshitishga loyiq bo'lgani, egasi og'ziga olib ulgurmasidan oldin uning qo'lida bo'ladi — bunga ishonchingiz komil bo'lsin, xo'jayinim.", "note": null},
  {"num": 40, "time": "00:03:14,520 --> 00:03:21,960", "arabic": "فَعُيُونُ خَادِمِكَ فَرَجٍ لَا تَعْرِفُ النَّوْمَ، لَا تَنْقُصُكَ الْفِطْنَةُ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Xizmatkoringiz Farajning ko'zlari uyquni bilmaydi. Farosating kam emas, Abu al-Abbos.", "note": null},
  {"num": 42, "time": "00:03:21,960 --> 00:03:32,960", "arabic": "اِسْمَعْ، اَلْأَيَّامُ الْقَادِمَةُ مُهِمَّةٌ وَحَاسِمَةٌ، فَاحْذَرْ أَنْ يَقَعَ مِنْكَ تَقْصِيرٌ", "segs": null, "full_uz": "Eshit — kelayotgan kunlar muhim va hal qiluvchidir, shuning uchun sendan sustkashlik yuz berishidan hazir bo'l.", "note": null},
  {"num": 45, "time": "00:03:32,960 --> 00:03:39,860", "arabic": "تَيَقُّظٌ تَيَقُّظٌ وَالْحَذَرَ الْحَذَرَ، تُوصِي خَادِمًا حَرِيصًا وَمُخْلِصًا يَا مَوْلَايَ", "segs": null, "full_uz": "Uyg'oqlik, uyg'oqlik va ehtiyot, ehtiyot! Vasiyatingiz — sinchkov va sodiq xizmatkorga, xo'jayinim.", "note": null},
  {"num": 48, "time": "00:03:39,860 --> 00:03:47,680", "arabic": "إِنَّنَا نُرِيدُ أَنْ نَرَى أَفْعَالَكَ لَا أَقْوَالَكَ، وَلَخَذَلْتُكَ يَوْمًا حَتَّى أَخْذُلَكَ الْآنَ", "segs": null, "full_uz": "Biz senda gapingni emas, ishingni ko'rishni istaymiz — men seni bugungacha bir kun ham xor qilmaganman, hozir ham xor qilmayman.", "note": null},
  {"num": 50, "time": "00:03:47,680 --> 00:04:02,000", "arabic": "تُرَى هَلْ كَانَ صَائِبًا انْقِطَاعُكَ هَذِهِ الْفَتْرَةَ عَنِ الْأَمِينِ يَا ابْنَ الْأَشْرَسِ؟", "segs": null, "full_uz": "Qiziq, bu muddatda al-Amindan uzoqlashib turishing to'g'ri bo'ldimikan, Ibn al-Ashras?", "note": null},
  {"num": 51, "time": "00:04:02,000 --> 00:04:09,860", "arabic": "لَعَلَّهُ يُحَدِّثُ نَفْسَهُ الْآنَ أَنِّي غَاضِبٌ لِمَا قَالَهُ بِحَقِّ صَاحِبِ الْمَرِيسِيِّ", "segs": null, "full_uz": "Balki u hozir o'zicha o'ylab, al-Marisiy egasi haqida aytganidan g'azablanganman deb bilar.", "note": null},
  {"num": 53, "time": "00:04:09,860 --> 00:04:18,360", "arabic": "يَجِبُ أَلَّا أُثِيرَ نَقِمَةَ هَذَا الظَّالِمِ عَلَيَّ، أَجَلْ، يَجِبُ عَلَيَّ أَنْ أَزُورَهُ", "segs": null, "full_uz": "Bu zolimning g'azabini o'zimga qaratmasligim kerak. Ha, uni ziyorat qilishim kerak.", "note": null},
  {"num": 56, "time": "00:04:18,360 --> 00:04:24,139", "arabic": "فَالنَّجَاةُ مِنَ الْأَشْرَارِ مِفْتَاحُهَا مَعْرِفَةُ الْأَخْبَارِ", "segs": null, "full_uz": "Yovuzlardan qutulishning kaliti — xabarlardan xabardor bo'lishdir.", "note": null},
  {"num": 58, "time": "00:04:39,860 --> 00:04:48,780", "arabic": "تَفَضَّلْ يَا شَيْخُ، بَارَكَ اللَّهُ فِيكَ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Marhamat, shayx. Alloh senga barakot bersin, Ibn Hanbal.", "note": null},
  {"num": 60, "time": "00:04:48,780 --> 00:04:53,960", "arabic": "جَزَاكَ اللَّهُ خَيْرًا، سَلَّمَ اللَّهُ يَمِينَكَ", "segs": null, "full_uz": "Alloh senga yaxshilik bersin. Alloh o'ng qo'lingni saqlasin.", "note": null},
  {"num": 62, "time": "00:04:58,280 --> 00:05:01,840", "arabic": "مَعْرِفَتُنَا بِكَ يَغْبِطُنَا عَلَيْهَا الْحُسَّادُ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Sizni tanishimizga hasadgo'ylar hasad qiladi, Abu Abdulloh.", "note": null},
  {"num": 63, "time": "00:05:01,840 --> 00:05:11,780", "arabic": "وَغِبْطَتِي لَكُمْ لَا تَقِلُّ عَنْ غِبْطَتِكُمْ لِي يَا طُلَّابَ حَدِيثِ رَسُولِ اللَّهِ، أَنْتُمْ تُذَكِّرُونَنِي بِأَصْحَابِهِ", "segs": null, "full_uz": "Sizlarga bo'lgan hasadim ham sizniki-dan kam emas, ey Rasululloh hadisining talabalari — sizlar menga uning sahobalarini eslatasizlar.", "note": null},
  {"num": 65, "time": "00:05:11,780 --> 00:05:20,399", "arabic": "بَارَكَ اللَّهُ فِيكُمْ وَفِي أَمْثَالِكُمْ، لَقَدْ حَفِظْتُمْ لَنَا سُنَّةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Alloh sizlarga va sizga o'xshaganlarga barakot bersin — bizga Rasululloh sollallohu alayhi va sallamning sunnatini saqlab qoldingiz.", "note": null},
  {"num": 68, "time": "00:05:20,399 --> 00:05:27,860", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا أَبَا عَبْدِ اللَّهِ، طُلَّابُ حَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Alloh senga yaxshilik bersin, Abu Abdulloh — Rasululloh sollallohu alayhi va sallam hadisining talabalari.", "note": null},
  {"num": 70, "time": "00:05:27,860 --> 00:05:34,379", "arabic": "خَيْرُ مَنْ يَتَقَرَّبُ إِلَى اللَّهِ بِصُحْبَتِهِمْ، وَقَدْ قُلْتُ فِي ذَلِكَ شِعْرًا", "segs": null, "full_uz": "Ularning suhbati bilan Allohga yaqinlashishning eng yaxshi yo'li — shu haqda bir she'r aytgan edim.", "note": null},
  {"num": 72, "time": "00:05:34,379 --> 00:05:37,060", "arabic": "أَتَسْمَعُونَ؟ أَسْمِعْنَا رَحِمَكَ اللَّهُ", "segs": null, "full_uz": "Eshitasizlarmi? Aytib bering, Alloh sizga rahmat qilsin.", "note": null},
  {"num": 74, "time": "00:05:37,060 --> 00:05:44,459", "arabic": "أُحِبُّ الصَّالِحِينَ وَلَسْتُ مِنْهُمْ، لَعَلِّي أَنْ أَنَالَ بِهِمْ شَفَاعَةً", "segs": null, "full_uz": "Solihlarni sevaman, garchi ulardan bo'lmasam ham — balki ular orqali shafoatga erishaman.", "note": null},
  {"num": 76, "time": "00:05:44,459 --> 00:05:51,139", "arabic": "وَأَكْرَهُ مَنْ تِجَارَتُهُ الْمَعَاصِي، وَإِنْ كُنَّا سَوَاءً فِي الْبِضَاعَةِ", "segs": null, "full_uz": "Va gunohlardan savdo qiluvchini yomon ko'raman, garchi molimiz bir xil bo'lsa ham.", "note": "اَلْبِضَاعَة — bu yerda majoziy ma'noda «amal» yoki «gunoh»ni anglatadi, savdo istiorasi."},
  {"num": 78, "time": "00:05:51,139 --> 00:05:59,100", "arabic": "تُحِبُّ الصَّالِحِينَ وَأَنْتَ مِنْهُمْ، لَعَلَّهُمْ يَنَالُوا بِكَ الشَّفَاعَةَ", "segs": null, "full_uz": "Solihlarni sevasan, o'zing ham ulardansan — balki ular sen orqali shafoatga erishar.", "note": null},
  {"num": 80, "time": "00:05:59,100 --> 00:06:05,959", "arabic": "وَتَكْرَهُ مَنْ تِجَارَتُهُ الْمَعَاصِي، حَمَاكَ اللَّهُ مِنْ تِلْكَ الْبِضَاعَةِ", "segs": null, "full_uz": "Gunohlardan savdo qiluvchini yomon ko'rasan — Alloh seni o'sha moldan asrasin.", "note": null},
  {"num": 82, "time": "00:06:05,959 --> 00:06:12,359", "arabic": "اَللَّهُمَّ آمِينَ، أَحْسَنْتَ يَا ابْنَ حَنْبَلٍ أَحْسَنْتَ، بَارَكَ اللَّهُ فِيكَ", "segs": null, "full_uz": "Omin, Allohim. Barakalla, Ibn Hanbal, barakalla. Alloh senga barakot bersin.", "note": null},
  {"num": 85, "time": "00:06:12,359 --> 00:06:19,620", "arabic": "مَا هَذَا يَا ابْنَ حَنْبَلٍ مَا هَذَا؟ سَبَقْتَنِي إِلَى الشِّعْرِ أَيْضًا، أَيْنَ تَذْهَبُ يَا ابْنَ نُوحٍ بِنَفْسِكَ بَيْنَ الشُّعَرَاءِ", "segs": null, "full_uz": "Bu nima, Ibn Hanbal, bu nima? She'rda ham mendan o'zib ketding-a. Qayoqqa ketyapsan, Ibn Nuh, o'zingni shoirlar orasiga qo'shib?", "note": null},
  {"num": 88, "time": "00:06:35,959 --> 00:06:44,799", "arabic": "تَأَخَّرْتَ يَا أَبَا هَاشِمٍ، تَحَرَّقْتُ مِنَ الِانْتِظَارِ", "segs": null, "full_uz": "Kechikding, Abu Hoshim — kutishdan yonib ketdim.", "note": null},
  {"num": 89, "time": "00:06:44,799 --> 00:06:53,579", "arabic": "اَلْحَقُّ يَا ابْنَ الْأَشْرَسِ إِنَّ أَمِيرَ الْمُؤْمِنِينَ مَشْغُولٌ وَلَنْ يَسْتَطِيعَ أَنْ يَرَاكَ الْآنَ", "segs": null, "full_uz": "Haqiqat shuki, Ibn al-Ashras, Amir al-Mo'minin band va hozir sizni ko'rolmaydi.", "note": null},
  {"num": 91, "time": "00:06:53,579 --> 00:07:02,679", "arabic": "حَقًّا مَشْغُولٌ؟ إِنَّهُ مَشْغُولٌ أَيْ مِنْ شُغْلِهِ", "segs": null, "full_uz": "Rostdan bandmi? U o'z ishi bilan band-da.", "note": null},
  {"num": 93, "time": "00:07:03,680 --> 00:07:19,680", "arabic": "حَسَنًا، أَعُودُ إِلَيْهِ مَرَّةً أُخْرَى، أَسْتَوْدِعُكَ اللَّهَ يَا أَبَا هَاشِمٍ", "segs": null, "full_uz": "Xo'p, unga yana boshqa vaqt qaytaman. Seni Allohga topshiraman, Abu Hoshim.", "note": null},
  {"num": 97, "time": "00:07:25,680 --> 00:07:30,680", "arabic": "أَخْبَرَنِي أَمِيرُ الْمُؤْمِنِينَ إِنَّهُ سَيُرْسِلُ فِي طَلَبِكَ إِنْ أَرَادَكَ", "segs": null, "full_uz": "Amir al-Mo'minin menga aytdi — agar seni chaqirsa, orqangdan yuboraman, dedi.", "note": null},
  {"num": 99, "time": "00:07:30,680 --> 00:07:39,920", "arabic": "لَمْ أَفْهَمْ، اَللَّبِيبُ مِنَ الْإِشَارَةِ يَفْهَمُ، إِنِ احْتَاجَكَ أَمِيرُ الْمُؤْمِنِينَ سَيُرْسِلُ فِي طَلَبِكَ", "segs": null, "full_uz": "Tushunmadim. Zukko kishi ishoradan ham tushunadi — agar Amir al-Mo'minin senga muhtoj bo'lsa, orqangdan yuboradi.", "note": null},
  {"num": 103, "time": "00:07:39,920 --> 00:07:51,120", "arabic": "إِذَنْ فَالْخَبَرُ حَقٌّ كَمَا قُلْتَ، أَجَلْ يَا مَوْلَايَ", "segs": null, "full_uz": "Demak, xabar aytganingdek to'g'ri ekan. Ha, xo'jayinim.", "note": null},
  {"num": 105, "time": "00:07:51,120 --> 00:07:59,439", "arabic": "اَلْأَمِينُ أَمَرَ بِأَنْ يُدْعَى لِابْنِهِ مُوسَى بَعْدَهُ وَبَعْدَكَ فِي الْخُطْبَةِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Al-Amin xutbada o'g'li Musoga sendan keyin va o'zidan keyin dua qilinishini buyurdi. La havla va la quvvata illa billah.", "note": null},
  {"num": 108, "time": "00:07:59,439 --> 00:08:03,100", "arabic": "هَذَا الَّذِي كُنْتُ أَخْشَاهُ يَا مَوْلَايَ", "segs": null, "full_uz": "Bu men qo'rqib turgan narsa edi, xo'jayinim.", "note": null},
  {"num": 109, "time": "00:08:03,100 --> 00:08:10,480", "arabic": "إِنَّهَا وَلَا شَكَّ تَدْبِيرٌ مِنْ تَدَابِيرِ ابْنِ الرَّبِيعِ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Bu, shubhasiz, Ibn ar-Rabi'ning tadbirlaridan biri, Abu al-Abbos.", "note": null},
  {"num": 110, "time": "00:08:10,480 --> 00:08:17,360", "arabic": "وَلَا شَكَّ وَلَا شَكَّ، وَلَكِنْ مَا الَّذِي سَتَفْعَلُهُ إِزَاءَ ذَلِكَ يَا مَوْلَايَ؟", "segs": null, "full_uz": "Shubhasiz, shubhasiz. Ammo bunga qarshi nima qilmoqchisiz, xo'jayinim?", "note": null},
  {"num": 112, "time": "00:08:17,360 --> 00:08:26,680", "arabic": "إِنَّ أَخِي الْمَأْمُونَ يُجْبِرُنِي عَلَى أَشْيَاءَ لَا رَغْبَةَ لِي حَتَّى بِذِكْرِهَا", "segs": null, "full_uz": "Ukam al-Ma'mun meni hatto zikr qilishga ham istagim bo'lmagan narsalarga majburlamoqda.", "note": null},
  {"num": 113, "time": "00:08:26,680 --> 00:08:36,440", "arabic": "اَلرَّأْيُ أَنْ يَكُونَ الرَّدُّ عَلَى مَا فَعَلَهُ الْأَمِينُ قَوِيًّا وَحَاسِمًا حَتَّى لَا يَطْغَى وَيَتَجَبَّرَ", "segs": null, "full_uz": "Fikrim shuki, al-Aminning qilganiga javob kuchli va qat'iy bo'lishi kerak, toki u haddan oshib, o'zini yuqori tutmasin.", "note": null},
  {"num": 115, "time": "00:08:36,440 --> 00:08:47,279", "arabic": "اِسْمَعْ يَا أَبَا الْعَبَّاسِ، سَأَقْطَعُ عَنْهُ الْبَرِيدَ وَأُسْقِطُ اسْمَهُ مِنَ الطُّرُزِ وَالنُّقُودِ", "segs": null, "full_uz": "Eshit, Abu al-Abbos — men undan pochtani uzaman va uning ismini to'nlar va pullardan tushiraman.", "note": "اَلطِّرَاز — hukmdorlar nomi yozilgan rasmiy matolar/liboslar, ularda ism o'chirilishi ozorlashning ramzi."},
  {"num": 117, "time": "00:08:47,279 --> 00:08:52,360", "arabic": "هَذِهِ بِتِلْكَ، لَعَلَّهُ يَعُودُ إِلَى رُشْدِهِ", "segs": null, "full_uz": "Bu — o'shaniki uchun. Balki o'ziga kelib qolar.", "note": null},
  {"num": 119, "time": "00:08:52,360 --> 00:08:56,259", "arabic": "هَذَا هُوَ الرَّأْيُ يَا وَلِيَّ الْعَالَمِ", "segs": null, "full_uz": "Fikrim shu, ey olam vaziri.", "note": null},
  {"num": 121, "time": "00:08:56,259 --> 00:09:06,939", "arabic": "هَؤُلَاءِ الْقَوْمُ غَرَّهُمْ حِلْمُكَ عَلَيْهِمْ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Bu qavmni sizning ularga bo'lgan halimligingiz aldab qo'ygan, ey Amir al-Mo'minin.", "note": null},
  {"num": 122, "time": "00:09:16,080 --> 00:09:22,279", "arabic": "مَنْ غَرَّهُ حِلْمِي وَصَفْحِي فَتَكَ بِهِ حَزْمِي وَسَيْفِي يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Halim va afvim uni aldagan bo'lsa, uni qat'iyatim va qilichim halok qiladi, Abu al-Abbos.", "note": null},
  {"num": 124, "time": "00:09:22,279 --> 00:09:27,280", "arabic": "لَا أَدْرِي يَا مَوْلَايَ مِنْ أَيْنَ أَتَتْهُمُ الْجُرْأَةُ لِيَفْعَلُوا مَا فَعَلُوهُ؟", "segs": null, "full_uz": "Bilmayman, xo'jayinim, qilgan ishlarini qilishga bu jasoratni qayerdan olishdi?", "note": null},
  {"num": 126, "time": "00:09:27,280 --> 00:09:36,440", "arabic": "اِمْتَنَعُوا عَنِ الْمَجِيءِ أَوَّلًا، ثُمَّ هَا هُمْ يَقْطَعُونَ الطَّرِيقَ عَنْ بَغْدَادَ، وَبَعْدَ ذَلِكَ يُسْقِطُونَ اسْمَ أَمِيرِ الْمُؤْمِنِينَ مِنَ الطُّرُزِ وَالنُّقُودِ", "segs": [{"ar": "اِمْتَنَعُوا عَنِ الْمَجِيءِ أَوَّلًا", "uz": "Avval kelishdan bosh tortishdi"}, {"ar": "ثُمَّ هَا هُمْ يَقْطَعُونَ الطَّرِيقَ عَنْ بَغْدَادَ", "uz": "keyin mana — Bag'dodga yo'lni to'sishdi"}, {"ar": "وَبَعْدَ ذَلِكَ يُسْقِطُونَ اسْمَ أَمِيرِ الْمُؤْمِنِينَ مِنَ الطُّرُزِ وَالنُّقُودِ", "uz": "undan keyin esa Amir al-Mo'mininning ismini to'nlar va pullardan tushirishdi"}], "full_uz": "Avval kelishdan bosh tortishdi, keyin mana — Bag'dodga yo'lni to'sishdi, undan keyin esa Amir al-Mo'mininning ismini to'nlar va pullardan tushirishdi.", "note": null},
  {"num": 129, "time": "00:09:36,440 --> 00:09:39,560", "arabic": "اَللَّهُ أَعْلَمُ، اَللَّهُ أَعْلَمُ مَاذَا يُرِيدُونَ", "segs": null, "full_uz": "Alloh biladi. Alloh biladi, ular nima istashadi.", "note": null},
  {"num": 131, "time": "00:09:39,560 --> 00:09:49,360", "arabic": "يَبْدُو أَنَّهُمْ مَاضُونَ فِي طَرِيقٍ لَا يَعْرِفُونَ مِنْهُ الْعَوْدَةَ يَا مَوْلَايَ، بَلْ هُوَ ضَرْبُ هَلَاكِهِمْ أَيُّهَا الْحَارِثُ", "segs": null, "full_uz": "Ular qaytishni bilmaydigan yo'lda ketayotganga o'xshaydi, xo'jayinim. Yo'q, bu ularning halokat yo'lidir, ey Horis.", "note": null},
  {"num": 133, "time": "00:09:49,360 --> 00:09:56,100", "arabic": "أُقْسِمُ أَنَّهُمْ سَيَنْدَمُونَ عَلَى مَا فَعَلُوهُ، وَإِذَا كَانَ أَخِي", "segs": null, "full_uz": "Qasam ichamanki, qilgan ishlariga pushaymon bo'lishadi. Va agar ukam...", "note": null},
  {"num": 135, "time": "00:09:56,100 --> 00:10:04,980", "arabic": "أَخِي الْمَأْمُونُ أَصْبَحَ مُضِيَّةً لِابْنِ سَهْلٍ وَأَتْرَابِهِ، فَسَأَعْرِفُ كَيْفَ أُوَعِّدُ مَلِيءَ صَوَابِهَا", "segs": null, "full_uz": "Ukam al-Ma'mun Ibn Sahl va uning kabilarning quroliga aylanib qolgan bo'lsa, men to'g'ri javobni qanday berishni bilaman.", "note": null},
  {"num": 138, "time": "00:10:04,980 --> 00:10:11,639", "arabic": "وَإِذَا كَانَ هَذَا الْأَمْرُ قَدْ أَعْيَا الْحَلِيمَ", "segs": null, "full_uz": "Va agar bu ish halim odamni ojiz qoldirgan bo'lsa.", "note": null},
  {"num": 140, "time": "00:10:11,639 --> 00:10:17,879", "arabic": "فَإِنَّهُ لَنْ يُعْيِيَ الْحَازِمَ، فَلْيَنْتَظِرْ مِنِّي بَطْشَةً", "segs": null, "full_uz": "U qat'iyatli kishini ojiz qoldirmaydi — mendan bir jazoni kutsin.", "note": null},
  {"num": 142, "time": "00:10:17,879 --> 00:10:23,100", "arabic": "يَشِيبُ مِنْهَا الْوَلِيدُ، هُمْ مَنْ كَتَبُوا نِهَايَتَهُمْ بِيَدِهِمْ يَا مَوْلَايَ", "segs": null, "full_uz": "Undan bola ham oqarib ketadi. Ular o'z oxirlarini o'z qo'llari bilan yozishdi, xo'jayinim.", "note": null},
  {"num": 144, "time": "00:10:23,100 --> 00:10:40,220", "arabic": "اِسْمَعْ يَا ابْنَ رَبِيعٍ، لَبَّيْكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Eshit, Ibn Rabi'. Labbayk, xo'jayinim.", "note": null},
  {"num": 146, "time": "00:10:40,220 --> 00:10:46,740", "arabic": "تَكْتُبُ كِتَابًا إِلَى الْأَمْصَارِ جَمِيعًا وَتَأْمُرُ الْوُلَاةَ فِيهِ", "segs": null, "full_uz": "Barcha viloyatlarga xat yozib, unda hokimlarga buyurasan.", "note": null},
  {"num": 148, "time": "00:10:50,019 --> 00:11:00,199", "arabic": "أَنْ يُسْقَطَ اسْمُ الْمَأْمُونِ مِنَ الْخُطْبَةِ، وَلَا يَبْقَى إِلَّا اسْمُ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Al-Ma'mun ismi xutbadan tushirilishini, faqat Amir al-Mo'minin ismi qolishini.", "note": null},
  {"num": 150, "time": "00:11:00,199 --> 00:11:03,860", "arabic": "وَالْأَمِيرِ مُوسَى بْنِ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Hamda Amir al-Mo'mininning o'g'li Amir Muso ismini.", "note": null},
  {"num": 151, "time": "00:11:15,860 --> 00:11:19,600", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ أَهْلًا يَا شَفِيعُ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom va rahmatulloh, xush kelibsiz, Shafi'.", "note": null},
  {"num": 153, "time": "00:11:19,600 --> 00:11:26,899", "arabic": "لَيْسَ مِنْ عَادَتِكَ أَنْ تَدْخُلَ عَلَيَّ بِهَذَا الْوَجْهِ الْجَامِدِ، أَرْجُو أَنْ يَكُونَ خَيْرًا", "segs": null, "full_uz": "Bu qattiq yuz bilan yonimga kirish odating emas — umid qilamanki, xayrli bo'lsin.", "note": null},
  {"num": 155, "time": "00:11:26,899 --> 00:11:34,580", "arabic": "أَيُّ شَرٍّ سَيُصِيبُ الْمُسْلِمِينَ إِنِ اسْتَفْحَلَ الْخِلَافُ وَأَضْرَمَ نَارَهُ الْحَاقِدُونَ", "segs": null, "full_uz": "Agar ixtilof kuchayib, hasadgo'ylar uning o'tini yoqsa, musulmonlarga qanday yovuzlik yetadi.", "note": null},
  {"num": 156, "time": "00:11:34,580 --> 00:11:41,180", "arabic": "اَللَّهُمَّ أَطْفِئْ هَذِهِ النَّائِرَةَ بِلُطْفِكَ يَا رَبِّ، يَا رَبِّ", "segs": null, "full_uz": "Allohim, bu yong'inni lutfing bilan o'chirgin, ey Rabbim. Ey Rabbim.", "note": "اَلنَّائِرَة — yonib turgan ziddiyat yoki fitna, majoziy ma'noda."},
  {"num": 158, "time": "00:11:43,820 --> 00:11:46,019", "arabic": "وَلَكِنَّهُ أَخُوكَ عَلَى كُلِّ حَالٍ", "segs": null, "full_uz": "Har holda, u sening akangku.", "note": null},
  {"num": 159, "time": "00:11:46,019 --> 00:11:53,740", "arabic": "لَوْ كَانَ أَخِي حَقًّا لَمَا أَطَاعَ كِلَابَ خُرَاسَانَ وَضَرَبَ عَرْضَ الْحَائِطِ بِكُلِّ رَسَائِلَ إِلَيْهِ", "segs": null, "full_uz": "Agar u haqiqiy akam bo'lganida, Xuroson itlariga itoat qilib, menga yuborilgan barcha xatlarni chetga uloqtirmagan bo'lardi.", "note": null},
  {"num": 161, "time": "00:11:53,740 --> 00:12:00,899", "arabic": "لَقَدْ أَسْلَمَ نَفْسَهُ لِلْمَارِقِينَ وَأَصْغَى لِلَّذِينَ يُرِيدُونَ هَدْمَ مَا بَنَاهُ ابْنُ الْعَبَّاسِ", "segs": null, "full_uz": "U o'zini yo'ldan chiqqanlarga topshirdi va Ibn al-Abbos qurgan narsani buzishni istaganlarga quloq soldi.", "note": null},
  {"num": 163, "time": "00:12:00,899 --> 00:12:07,399", "arabic": "أَوَقَدْ نَسِيَ الْمَأْمُونُ؟ لَا وَاللَّهِ، بَلْ أَظُنُّهُ قَدْ تَنَاسَى", "segs": null, "full_uz": "Al-Ma'mun unutdimi? Yo'q, Alloh haqi — balki bila-bila unutgandir.", "note": null},
  {"num": 165, "time": "00:12:07,399 --> 00:12:16,000", "arabic": "وَلَكِنْ هَيْهَاتَ هَيْهَاتَ لَهُ وَلَهُمْ، أَيُّ عَقْلٍ أَنْ تُنْقَضَ مَا أَبْرَمَهُ أَبُوكَ الرَّشِيدُ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Ammo unga ham, ularga ham qayta yo'q — otang ar-Rashid — Alloh unga rahmat qilsin — mahkam qilgan ahdni buzish qanday aqldan bo'ladi?", "note": null},
  {"num": 167, "time": "00:12:16,000 --> 00:12:22,000", "arabic": "لَوْ كَانَ أَبِي عَلَى قَيْدِ الْحَيَاةِ وَرَأَى مِنَ الْمَأْمُونِ مَا رَأَى لَفَعَلَ مِثْلَ مَا أَفْعَلُ أَوْ يَزِيدُ", "segs": null, "full_uz": "Agar otam tirik bo'lganida va al-Ma'munda men ko'rganimni ko'rganida, mendan ham ortiqroq ish qilgan bo'lardi.", "note": null},
  {"num": 170, "time": "00:12:22,000 --> 00:12:30,000", "arabic": "يَا مُحَمَّدُ، لَا تُجَرِّئِ الْقُوَّادَ عَلَى الْخَلْعِ فَيَخْلَعُوكَ، وَلَا تَحْمِلْهُمْ عَلَى نَكْثِ الْعُهُودِ فَيَنْكُثَ عَهْدَكَ وَبَيْعَتَكَ", "segs": [{"ar": "يَا مُحَمَّدُ، لَا تُجَرِّئِ الْقُوَّادَ عَلَى الْخَلْعِ فَيَخْلَعُوكَ", "uz": "Ey Muhammad, sarkardalarni taxtdan tushirishga jur'atlantirma, yo'qsa seni ham tushirishadi"}, {"ar": "وَلَا تَحْمِلْهُمْ عَلَى نَكْثِ الْعُهُودِ فَيَنْكُثَ عَهْدَكَ وَبَيْعَتَكَ", "uz": "va ularni ahdlarni buzishga undama, aks holda ular ham ahding va bay'atingni buzishadi"}], "full_uz": "Ey Muhammad, sarkardalarni taxtdan tushirishga jur'atlantirma, yo'qsa seni ham tushirishadi — va ularni ahdlarni buzishga undama, aks holda ular ham ahding va bay'atingni buzishadi.", "note": null},
  {"num": 173, "time": "00:12:30,000 --> 00:12:34,000", "arabic": "فَإِنَّ الْغَادِرَ مَخْذُولٌ وَالنَّاكِثَ مَغْلُولٌ", "segs": null, "full_uz": "Chunki xoinlik qiluvchi xor bo'ladi, ahdni buzuvchi esa kishanlanadi.", "note": null},
  {"num": 175, "time": "00:12:36,000 --> 00:12:40,240", "arabic": "قَدْ كَانَ مَا كَانَ، قَدْ كَانَ مَا كَانَ", "segs": null, "full_uz": "Bo'lgani bo'ldi. Bo'lgani bo'ldi.", "note": null},
  {"num": 177, "time": "00:12:40,240 --> 00:12:51,120", "arabic": "أَيْنَ تَذْهَبُ بِالْعُهُودِ الَّتِي قَطَعْتَهَا أَمَامَ اللَّهِ عَلَى نَفْسِكَ؟", "segs": null, "full_uz": "O'zingga Alloh oldida bergan ahdlaringni qayerga qo'yasan?", "note": null},
  {"num": 178, "time": "00:12:51,120 --> 00:12:58,179", "arabic": "يَعْلَمُ اللَّهُ أَنَّنِي لَمْ آلُ جُهْدًا فِي اسْتِرْضَاءِ أَخِي الْمَأْمُونِ، لَكِنَّهُ أَصَمَّ أُذُنَيْهِ عَنْ نُصْحِي", "segs": null, "full_uz": "Alloh biladiki, ukam al-Ma'munni rozi qilishda hech qanday kuchni ayamadim, ammo u nasihatimga qulog'ini bekitdi.", "note": null},
  {"num": 180, "time": "00:12:58,179 --> 00:13:04,720", "arabic": "وَكُتُبُ الْعُهُودِ الَّتِي عَلَّقَهَا الرَّشِيدُ رَحِمَهُ اللَّهُ أَصْبَحَتْ مِنَ الْمَاضِي", "segs": null, "full_uz": "Ar-Rashid — Alloh unga rahmat qilsin — osib qo'ygan ahdnoma kitoblari o'tmishga aylandi.", "note": null},
  {"num": 182, "time": "00:13:08,000 --> 00:13:12,000", "arabic": "مِنَ الْمَاضِي؟ كَيْفَ ذَلِكَ؟", "segs": null, "full_uz": "O'tmishgami? Bu qanday?", "note": null},
  {"num": 184, "time": "00:13:14,220 --> 00:13:19,620", "arabic": "قَدْ أَرْسَلْتُ إِلَى وَالِي مَكَّةَ الْمُكَرَّمَةِ أَنْ يُخْرِجَ تِلْكَ الْعُهُودَ مِنَ الْكَعْبَةِ", "segs": null, "full_uz": "Makka Mukarrama hokimiga xat yubordim — o'sha ahdnomalarni Ka'badan chiqarsin deb.", "note": null},
  {"num": 186, "time": "00:13:19,620 --> 00:13:26,120", "arabic": "وَيَبْعَثَ بِهَا إِلَيَّ حَتَّى أُمَزِّقَهَا، لِكَيْ يَعْرِفَ ذَلِكَ الْمَأْمُونُ فِي خُرَاسَانَ", "segs": null, "full_uz": "Va ularni menga yuborsin, toki men yirtib tashlayman — shu Xurosondagi al-Ma'mun bilib qo'ysin.", "note": null},
  {"num": 188, "time": "00:13:26,120 --> 00:13:29,000", "arabic": "أَنَّ كِلَابَهُ أَوْدَوْا بِهِ إِلَى التَّهْلُكَةِ", "segs": null, "full_uz": "Uning itlari uni halokatga olib borganini.", "note": null},
  {"num": 189, "time": "00:13:29,679 --> 00:13:35,820", "arabic": "اِتَّقِ اللَّهَ فِي أَخِيكَ يَا مُحَمَّدُ، إِنَّهُ أَخُوكَ وَبَقِيَّةُ أَبِيكَ", "segs": null, "full_uz": "Akangda Allohdan qo'rq, Muhammad — u sening akang va otangdan qolgan yagona yodgorlik.", "note": null},
  {"num": 191, "time": "00:13:35,820 --> 00:13:43,540", "arabic": "لَا تَقْطَعْ رَحِمَكَ بِغَوَايَةِ الدُّنْيَا وَمَكْرِ الْحَاقِدِينَ، أَأَنَا مَنْ بَدَأَ ذَلِكَ يَا أُمَّ الْأَمِينِ؟", "segs": null, "full_uz": "Dunyo va hasadgo'ylarning makriga uchib, qarindoshlik rishtangni uzma. Buni birinchi men boshlaganmanmi, ey al-Aminning onasi?", "note": null},
  {"num": 193, "time": "00:13:43,540 --> 00:13:47,260", "arabic": "بِاللَّهِ عَلَيْكِ قُولِي، أَأَنَا مَنْ بَدَأَ ذَلِكَ أَمْ هُوَ؟", "segs": null, "full_uz": "Alloh haqi, ayting — buni men boshladimmi yoki u?", "note": null},
  {"num": 195, "time": "00:13:47,260 --> 00:13:57,400", "arabic": "كِلَاكُمَا شَرِيكٌ فِي الْخَطَإِ وَضَحِيَّةُ مَكِيدَةٍ مَاكِرَةٍ، وَإِنْ كَانَ الْمَأْمُونُ قَدْ أَعْطَى أُذُنَهُ لِلْحَاقِدِينَ يُفْسِدُونَ مَا بَيْنَكَ وَبَيْنَهُ فَأَنْتَ تَحْذُو حَذْوَهُ", "segs": [{"ar": "كِلَاكُمَا شَرِيكٌ فِي الْخَطَإِ وَضَحِيَّةُ مَكِيدَةٍ مَاكِرَةٍ", "uz": "Ikkovingiz ham xatoda sherik va ayyor bir fitnaning qurbonisiz"}, {"ar": "وَإِنْ كَانَ الْمَأْمُونُ قَدْ أَعْطَى أُذُنَهُ لِلْحَاقِدِينَ يُفْسِدُونَ مَا بَيْنَكَ وَبَيْنَهُ", "uz": "al-Ma'mun sizning oraga fitna solayotgan hasadgo'ylarga qulog'ini bergan bo'lsa"}, {"ar": "فَأَنْتَ تَحْذُو حَذْوَهُ", "uz": "sen ham xuddi shu yo'lni tutyapsan"}], "full_uz": "Ikkovingiz ham xatoda sherik va ayyor bir fitnaning qurbonisiz — al-Ma'mun sizning oraga fitna solayotgan hasadgo'ylarga qulog'ini bergan bo'lsa, sen ham xuddi shu yo'lni tutyapsan.", "note": null},
  {"num": 199, "time": "00:13:57,400 --> 00:14:05,460", "arabic": "إِنَّ مَنْ مَعِي نُصَحَاءُ، اِسْتَعْمَلَهُمْ أَبِي هَارُونُ وَلَمْ يَخُنْ لَهُ عَهْدًا", "segs": null, "full_uz": "Mening yonimdagilar nasihatgo'ylardir — otam Horun ularni ishlatgan va ular unga ahdda xiyonat qilmagan.", "note": null},
  {"num": 201, "time": "00:14:05,460 --> 00:14:09,519", "arabic": "وَلَمْ يَنْقُضْ مِيثَاقًا", "segs": null, "full_uz": "Va ahdnomani buzmagan.", "note": null},
  {"num": 203, "time": "00:14:09,519 --> 00:15:34,460", "arabic": "وَلَكِنِ الْعُهُودُ تُنْكَثُ وَالْمَوَاثِيقُ تُنْقَضُ", "segs": null, "full_uz": "Ammo ahdlar buziladi, ahdnomalar bekor qilinadi.", "note": null},
  {"num": 208, "time": "00:15:34,460 --> 00:15:39,460", "arabic": "جَلَّا أَحْضِرْ مَاءَهُنَّ", "segs": null, "full_uz": "Jalla, ularga suv keltir.", "note": null},
  {"num": 209, "time": "00:15:40,460 --> 00:15:43,460", "arabic": "رَأَيْتُهَا الْخَبِيثَةَ", "segs": null, "full_uz": "Uni ko'rdim, yovuzni.", "note": null},
  {"num": 210, "time": "00:15:43,460 --> 00:15:47,460", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكِ السَّلَامُ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykim assalom.", "note": null},
  {"num": 212, "time": "00:15:47,460 --> 00:15:50,460", "arabic": "جِئْتَ مِنَ الدُّكَّانِ؟ أَجَلْ يَا أُمِّي جِئْتُ", "segs": null, "full_uz": "Do'kondan keldingmi? Ha, onajon, keldim.", "note": null},
  {"num": 214, "time": "00:15:50,460 --> 00:15:56,460", "arabic": "وَالَّذِي جَاءَ بِكِ بَاكِرًا؟ جِئْتُ كَيْ يُعَاقَبَ هَذَا الْفَتَى الْكَاذِبُ", "segs": null, "full_uz": "Seni erta keltirgan narsa nima edi? Bu yolg'onchi bolaning jazolanishi uchun keldim.", "note": null},
  {"num": 216, "time": "00:15:56,460 --> 00:16:03,460", "arabic": "عَمِيلٌ يَا عَمِيلُ عَمِيلٌ عَمِيلٌ، وَمَا الَّذِي فَعَلَهُ حَتَّى يَسْتَحِقَّ الْعِقَابَ؟", "segs": null, "full_uz": "Sotqin, ey sotqin, sotqin, sotqin! U jazoga loyiq bo'lish uchun nima qilgan?", "note": null},
  {"num": 218, "time": "00:16:03,460 --> 00:16:07,019", "arabic": "تَخَيَّلِي يَا أُمِّي إِنَّ عُمَيْرَ يَكْذِبُ، يَكْذِبُ عَلَى أَبِيهِ", "segs": null, "full_uz": "Tasavvur qiling, onajon — Umayr yolg'on gapirmoqda, otasiga yolg'on gapirmoqda.", "note": null},
  {"num": 220, "time": "00:16:07,019 --> 00:16:09,900", "arabic": "قَالَ لِي إِنَّ شَيْخَهُ قَدْ مَاتَ، وَمَا أَدْرَاكَ؟", "segs": null, "full_uz": "Menga «shayxim vafot etdi», dedi. Sen qayerdan bilding?", "note": null},
  {"num": 222, "time": "00:16:09,900 --> 00:16:14,480", "arabic": "رُبَّمَا يَكُونُ شَيْخُهُ قَدْ مَاتَ حَقًّا، سَأَلْتُ يَا أُمِّي، سَأَلْتُ", "segs": null, "full_uz": "Balki shayxi rostdan ham vafot etgandir. So'radim, onajon, so'radim.", "note": null},
  {"num": 224, "time": "00:16:14,480 --> 00:16:19,639", "arabic": "كُلُّ مَا فِي الْأَمْرِ أَنَّ شَيْخَهُ قَدْ غَلَبَ عَلَيْهِ النُّعَاسُ أَثْنَاءَ الدَّرْسِ فَنَامَ", "segs": null, "full_uz": "Ish faqat shundaki, uning shayxini dars vaqtida uyqu bosib, uxlab qolgan.", "note": null},
  {"num": 227, "time": "00:16:19,639 --> 00:16:22,940", "arabic": "فَعَرَّبَ عُمَيْرٌ، عُمَيْرُ عُمَيْرُ تَعَالَ يَا وَلَدُ", "segs": null, "full_uz": "Umayr esa hazillashib aytdi. Umayr, Umayr, kel bu yoqqa, bolam.", "note": null},
  {"num": 230, "time": "00:16:22,940 --> 00:16:27,420", "arabic": "تَعَالَ لِتَنَالَ عِقَابَكَ، عُمَيْرُ اِقْتَرِبْ", "segs": null, "full_uz": "Jazoyingni olish uchun kel. Umayr, yaqinroq kel.", "note": null},
  {"num": 233, "time": "00:16:27,420 --> 00:16:32,639", "arabic": "اِقْتَرِبْ إِنِّي، مَاذَا تُرِيدِينَ يَا أُمِّي؟ مَاذَا تُرِيدِينَ يَا أُمِّي؟", "segs": null, "full_uz": "Yaqinroq kel, men... Nima istaysiz, buvijon? Nima istaysiz, buvijon?", "note": null},
  {"num": 236, "time": "00:16:32,639 --> 00:16:36,559", "arabic": "اِقْتَرِبْ أَكْثَرَ، تُرِيدِينَ شَيْئًا قُولِي لِي، تَعَالَ أُمِّي مَا بِكِ", "segs": null, "full_uz": "Yaqinroq kel. Biror narsa kerakmi, aytib bering. Kel, buvijon, sizga nima bo'ldi?", "note": null},
  {"num": 239, "time": "00:16:36,559 --> 00:16:42,379", "arabic": "أَنْتَ هُوَ مَنْ يَسْتَحِقُّ الْعِقَابَ لِأَنَّكَ لَمْ تَعْرِفْ كَيْفَ تُرَبِّي أَبْنَاءَ", "segs": null, "full_uz": "Jazoga loyiq — bu sensan, chunki farzand tarbiyalashni bilmading.", "note": null},
  {"num": 241, "time": "00:16:42,379 --> 00:16:46,919", "arabic": "أَنْتَ هُوَ الَّذِي يَسْتَحِقُّ الْعِقَابَ، تَعَالَ إِلَى هُنَا", "segs": null, "full_uz": "Jazoga loyiq — bu sensan. Bu yoqqa kel.", "note": null},
  {"num": 243, "time": "00:16:46,919 --> 00:16:53,419", "arabic": "أَنْتَ وَزَوْجَتُكَ الْحَيْزَبُونُ، زَوْجَتُكَ الْحَيْزَبُونُ الْقَبِيحَةُ", "segs": null, "full_uz": "Sen va sening jodugar xotining, jodugar va xunuk xotining.", "note": "اَلْحَيْزَبُون — jodugar, badjahl kampir ma'nosidagi haqoratomuz so'z."},
  {"num": 245, "time": "00:16:53,419 --> 00:17:07,279", "arabic": "تُرَى مَا سَبَبُ هَذِهِ الْجُهُومَةِ يَا شَفِيعُ؟ أَهُوَ مَا أُفَكِّرُ فِيهِ أَنَا؟", "segs": null, "full_uz": "Qiziq, bu tund yuzning sababi nima, Shafi'? Menda o'ylagan narsammikan?", "note": "اَلْجُهُومَة — yuzning tund, xira ko'rinishi."},
  {"num": 247, "time": "00:17:07,279 --> 00:17:16,420", "arabic": "لَا لَا لَا أَظُنُّ، فَشَفِيعٌ لَمْ يَذْكُرْ هَذَا الشَّيْءَ مِنْ قَبْلُ أَمَامِي", "segs": null, "full_uz": "Yo'q, yo'q, o'ylamayman — Shafi' bu narsani ilgari mening oldimda tilga olmagan edi.", "note": null},
  {"num": 249, "time": "00:17:16,420 --> 00:17:56,179", "arabic": "وَإِنْ يَكُنْ، رُبَّمَا كَانَ يَكْتُمُهُ فِي نَفْسِهِ", "segs": null, "full_uz": "Bo'lsa ham, balki uni ichida yashirib yurgandir.", "note": null},
  {"num": 254, "time": "00:17:56,179 --> 00:18:05,819", "arabic": "أَنْتِ وَاهِمَةٌ يَا فَوْزُ، لَا أَظُنُّ شَفِيعًا يُفَكِّرُ بِهَذِهِ الطَّرِيقَةِ", "segs": null, "full_uz": "Xato o'ylayapsan, Favz — Shafi' bunday tarzda o'ylaydi deb bilmayman.", "note": null},
  {"num": 255, "time": "00:18:05,819 --> 00:18:12,359", "arabic": "وَمَا الَّذِي يَمْنَعُهُ مِنَ التَّفْكِيرِ فِي ذَلِكَ؟ أَلَيْسَ كُلُّ رَجُلٍ يَتَمَنَّى أَنْ يَكُونَ لَهُ أَوْلَادٌ يَأْنَسُ بِهِمْ", "segs": [{"ar": "وَمَا الَّذِي يَمْنَعُهُ مِنَ التَّفْكِيرِ فِي ذَلِكَ؟", "uz": "Uni shu haqda o'ylashdan nima to'sadi?"}, {"ar": "أَلَيْسَ كُلُّ رَجُلٍ يَتَمَنَّى أَنْ يَكُونَ لَهُ أَوْلَادٌ يَأْنَسُ بِهِمْ", "uz": "Har bir erkak farzand ko'rib ko'ngli yayrashini xohlamaydimi?"}], "full_uz": "Uni shu haqda o'ylashdan nima to'sadi? Har bir erkak farzand ko'rib ko'ngli yayrashini xohlamaydimi?", "note": null},
  {"num": 257, "time": "00:18:12,359 --> 00:18:18,899", "arabic": "وَيَحْمِلُوا اسْمَهُ فِي حَيَاتِهِ وَبَعْدَ مَمَاتِهِ؟ لَكِنَّ هَذَا الْأَمْرَ بِيَدِ اللَّهِ يَا فَوْزُ", "segs": null, "full_uz": "Va uning ismini hayotida ham, vafotidan keyin ham davom ettirishlarini? Ammo bu ish Allohning qo'lida, Favz.", "note": null},
  {"num": 259, "time": "00:18:18,900 --> 00:18:24,740", "arabic": "هُوَ مَنْ يَهَبُ مَنْ يَشَاءُ وَيَمْنَعُ مَنْ يَشَاءُ، وَشَفِيعٌ رَجُلٌ مُؤْمِنٌ", "segs": null, "full_uz": "U xohlaganiga beradi, xohlaganidan man qiladi — Shafi' esa mo'min kishidir.", "note": null},
  {"num": 261, "time": "00:18:24,740 --> 00:18:30,000", "arabic": "لَا أَظُنُّهُ يَعْتَرِضُ عَلَى قَضَاءِ اللَّهِ وَقَدَرِهِ، شَفِيعٌ مَعْذُورٌ", "segs": null, "full_uz": "Allohning qazo-qadariga e'tiroz bildiradi deb o'ylamayman. Shafi' ma'zur.", "note": null},
  {"num": 263, "time": "00:18:30,000 --> 00:18:36,720", "arabic": "مَعْذُورٌ فِيمَا يُفَكِّرُ فِيهِ إِذْ لَمْ يَرْزُقْنَا اللَّهُ أَوْلَادَهُ، هَيَّا يَا أُخَيَّ", "segs": null, "full_uz": "Alloh bizga farzand ato etmagani uchun o'ylagan narsasida ma'zur. Yur, singlim.", "note": null},
  {"num": 265, "time": "00:18:36,720 --> 00:18:45,780", "arabic": "أَبْعِدِي هَذِهِ الْأَفْكَارَ السَّيِّئَةَ عَنْ ذِهْنِكِ، مَا زِلْتِ فِي مُقْتَبَلِ الْعُمُرِ وَالْحَيَاةُ تَفْتَحُ لَكِ ذِرَاعَيْهَا", "segs": null, "full_uz": "Bu yomon fikrlarni miyangdan chiqar — sen hali umringning boshida, hayot senga qo'llarini ochyapti.", "note": null},
  {"num": 268, "time": "00:18:45,779 --> 00:18:51,920", "arabic": "وَمَا حَدِيثُكِ هَذَا إِلَّا وَهْمٌ وَخَيَالٌ، لَا أَدْرِي يَا شُعَيْنَاسُ لَا أَدْرِي", "segs": null, "full_uz": "Bu gaping esa faqat vahm va xayoldan boshqa narsa emas. Bilmayman, Shu'aynos, bilmayman.", "note": null},
  {"num": 270, "time": "00:18:51,920 --> 00:18:58,559", "arabic": "قَلْبِي يُحَدِّثُنِي أَنَّ ذَلِكَ مَا يَشْغَلُ بَالَ زَوْجِي، اَلْعُمْرُ أَمَامَكِ يَا أُخَيَّ", "segs": null, "full_uz": "Yuragim menga aytadiki, erimning fikrini band qilayotgan narsa shu. Umr hali oldingda, singlim.", "note": null},
  {"num": 272, "time": "00:18:58,559 --> 00:19:05,960", "arabic": "فَلَا تَيْأَسِي مِنْ رَحْمَةِ اللَّهِ، وَقَدْ يَكُونُ هُنَاكَ مَا يَشْغَلُ بَالَهُ غَيْرُ مَا تَظُنِّينَ", "segs": null, "full_uz": "Allohning rahmatidan umidsiz bo'lma — balki uning fikrini boshqa narsa band qilgandir, sen o'ylagandan boshqa.", "note": null},
  {"num": 274, "time": "00:19:05,960 --> 00:19:10,259", "arabic": "لَا أَدْرِي يَا شُعَيْنَاسُ لَا أَدْرِي، لَا أَدْرِي", "segs": null, "full_uz": "Bilmayman, Shu'aynos, bilmayman, bilmayman.", "note": null},
  {"num": 276, "time": "00:19:10,259 --> 00:19:16,839", "arabic": "هَوِّنِي عَلَيْكِ يَا أُخَيَّ، هَوِّنِي عَلَيْكِ", "segs": null, "full_uz": "O'zingga yengil ol, singlim, o'zingga yengil ol.", "note": null},
  {"num": 278, "time": "00:19:16,839 --> 00:19:40,619", "arabic": "أَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ إِلَيْكَ", "segs": null, "full_uz": "Sen Boy Zotsan, biz esa Senga muhtoj faqirlarmiz.", "note": null},
  {"num": 279, "time": "00:19:40,619 --> 00:19:46,519", "arabic": "أَنْتَ الْقَوِيُّ وَنَحْنُ الضُّعَفَاءُ إِلَيْكَ", "segs": null, "full_uz": "Sen Kuchli Zotsan, biz esa Sening oldingda ojizlarmiz.", "note": null},
  {"num": 280, "time": "00:19:46,519 --> 00:19:51,519", "arabic": "أَنْتَ الْعَزِيزُ وَنَحْنُ الْأَذِلَّاءُ إِلَيْكَ", "segs": null, "full_uz": "Sen Aziz Zotsan, biz esa Sening oldingda xorlarmiz.", "note": null},
  {"num": 281, "time": "00:19:52,480 --> 00:19:58,519", "arabic": "اَللَّهُمَّ يَا وَاصِلَ الْمُنْقَطِعِينَ أَوْصِلْنَا إِلَيْكَ", "segs": null, "full_uz": "Allohim, ey uzilganlarni ulovchi Zot, bizni O'zingga ulagin.", "note": null},
  {"num": 282, "time": "00:19:59,319 --> 00:20:04,519", "arabic": "اَللَّهُمَّ هَبْ لَنَا مِنْكَ عَمَلًا صَالِحًا يُقَرِّبُنَا إِلَيْكَ", "segs": null, "full_uz": "Allohim, bizga O'zingdan bizni O'zingga yaqinlashtiruvchi solih amal ato et.", "note": null},
  {"num": 283, "time": "00:20:05,559 --> 00:20:09,519", "arabic": "يَا اللَّهُ، يَا رَحِيمُ", "segs": null, "full_uz": "Ey Alloh, ey Rahim.", "note": null},
  {"num": 285, "time": "00:20:10,119 --> 00:20:13,000", "arabic": "يَا اللَّهُ", "segs": null, "full_uz": "Ey Alloh.", "note": null},
  {"num": 286, "time": "00:20:13,000 --> 00:20:25,299", "arabic": "لَا تُجْزِئُ صَلَاةٌ إِلَّا بِنِيَّةٍ، لِحَدِيثِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Niyatsiz namoz to'g'ri bo'lmaydi — Umar ibn al-Xattobdan, Alloh undan rozi bo'lsin, Payg'ambar sollallohu alayhi va sallamdan rivoyat qilingan hadisga ko'ra.", "note": "Bu — mashhur «Innamal a'malu bin-niyyat» (Amallar niyatlarga bog'liqdir) hadisiga ishora, Buxoriy va Muslim rivoyat qilgan."},
  {"num": 290, "time": "00:20:25,299 --> 00:20:29,119", "arabic": "إِنَّمَا الْأَعْمَالُ بِالنِّيَّةِ، أَمَّا الْإِيمَانُ", "segs": null, "full_uz": "Amallar faqat niyat bilandir. Iymonga kelsak esa.", "note": null},
  {"num": 292, "time": "00:20:29,119 --> 00:20:38,180", "arabic": "فَقَدْ كَانَ الْإِجْمَاعُ مِنَ الصَّحَابَةِ وَالتَّابِعِينَ مِنْ بَعْدِهِمْ أَنَّ الْإِيمَانَ قَوْلٌ وَعَمَلٌ وَنِيَّةٌ", "segs": null, "full_uz": "Sahobalar va ulardan keyingi tobe'inlarning ijmosi shuki, iymon — so'z, amal va niyatdir.", "note": null},
  {"num": 294, "time": "00:20:38,180 --> 00:20:47,380", "arabic": "لَا تُجْزِئُ وَاحِدَةٌ عَنِ الْأُخْرَى، وَصَلَّى اللَّهُ عَلَى مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ", "segs": null, "full_uz": "Ulardan biri boshqasi o'rniga o'tmaydi. Alloh Muhammadga, uning ahli va sahobalariga salovot va salom yo'llasin.", "note": null},
  {"num": 297, "time": "00:20:47,380 --> 00:20:52,360", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا أَبَا عَبْدِ اللَّهِ، إِذَنْ لِي يَا شَيْخَنَا", "segs": null, "full_uz": "Alloh senga yaxshilik bersin, Abu Abdulloh. Ijozat, shayximiz.", "note": null},
  {"num": 299, "time": "00:20:52,360 --> 00:21:00,900", "arabic": "يَا أَبَا الْمُغِيرَةِ، أَيْنَ صَاحِبُكَ لَمْ نَرَهُ مُنْذُ يَوْمَيْنِ؟", "segs": null, "full_uz": "Abu al-Mug'ira, do'stingiz qayerda — uni ikki kundan beri ko'rmayapmiz?", "note": null},
  {"num": 302, "time": "00:21:00,900 --> 00:21:06,460", "arabic": "اِبْنُ مُحَمَّدٍ، إِنَّهُ مَوْعُوكٌ قَلِيلًا، أَحْمَدُ مَرِيضٌ؟", "segs": null, "full_uz": "Muhammadning o'g'li — u biroz nogoron. Ahmad kasalmi?", "note": null},
  {"num": 304, "time": "00:21:06,460 --> 00:21:11,220", "arabic": "لِمَاذَا لَمْ تُخْبِرْنِي مِنْ قَبْلُ؟ إِنَّهُ وَعْكٌ بَسِيطٌ لَا دَاعِيَ لِلْقَلَقِ عَلَيْهِ يَا شَيْخَنَا", "segs": null, "full_uz": "Nega menga oldindan aytmading? Bu oddiy bir bezovtalik, uning uchun xavotirlanishga hojat yo'q, shayximiz.", "note": null},
  {"num": 306, "time": "00:21:11,220 --> 00:21:16,420", "arabic": "كَيْفَ لَا أَقْلَقُ يَا أَبَا الْمُغِيرَةِ؟ عَلَى مَنْ نَقْلَقُ إِذَنْ؟", "segs": null, "full_uz": "Qanday xavotirlanmayin, Abu al-Mug'ira? Unda kim uchun xavotirlanamiz?", "note": null},
  {"num": 308, "time": "00:21:16,420 --> 00:21:25,500", "arabic": "إِنَّ أَحْمَدَ وَاجِبُهُ كَبِيرٌ وَزِيَارَتُهُ عَلَيْنَا وَاجِبَةٌ، هَيَّا أَيُّهَا الْإِخْوَةُ لِنَزُورَ أَحْمَدَ بْنَ حَنْبَلٍ وَنَطْمَئِنَّ عَلَيْهِ", "segs": [{"ar": "إِنَّ أَحْمَدَ وَاجِبُهُ كَبِيرٌ وَزِيَارَتُهُ عَلَيْنَا وَاجِبَةٌ", "uz": "Ahmadning bizga bo'lgan haqi katta, uni ziyorat qilish bizga vojib"}, {"ar": "هَيَّا أَيُّهَا الْإِخْوَةُ لِنَزُورَ أَحْمَدَ بْنَ حَنْبَلٍ وَنَطْمَئِنَّ عَلَيْهِ", "uz": "yuring, birodarlar, Ahmad ibn Hanbalni ziyorat qilib, tinchligiga ishonch hosil qilaylik"}], "full_uz": "Ahmadning bizga bo'lgan haqi katta, uni ziyorat qilish bizga vojib — yuring, birodarlar, Ahmad ibn Hanbalni ziyorat qilib, tinchligiga ishonch hosil qilaylik.", "note": null},
  {"num": 310, "time": "00:21:25,500 --> 00:21:28,980", "arabic": "عَلَى بَرَكَةِ اللَّهِ، هَيَّا يَا أَبَا ثَوْرٍ", "segs": null, "full_uz": "Alloh barakasi bilan. Yur, Abu Savr.", "note": null},
  {"num": 312, "time": "00:21:28,980 --> 00:21:37,480", "arabic": "لَوْ أَجَّلْتَ ذَلِكَ إِلَى الصَّبَاحِ يَا أَبَا عَبْدِ اللَّهِ فَقَدْ تَأَخَّرَ الْوَقْتُ، لَا يَا أَبَا ثَوْرٍ", "segs": null, "full_uz": "Buni ertalabgacha kechiktirsangiz, Abu Abdulloh — vaqt kech bo'lib qoldi. Yo'q, Abu Savr.", "note": null},
  {"num": 314, "time": "00:21:37,480 --> 00:21:43,740", "arabic": "عِلْمُنَا بِمَرَضِهِ الْآنَ يُوجِبُ زِيَارَتَهُ الْآنَ، هَيَّا", "segs": null, "full_uz": "Uning kasalligidan hozir xabar topganimiz, hozir uni ziyorat qilishimizni vojib qiladi. Yur.", "note": null},
  {"num": 317, "time": "00:22:07,480 --> 00:22:20,000", "arabic": "رَحِمَكِ اللَّهُ يَا أُمَّ ثَابِتٍ", "segs": null, "full_uz": "Alloh senga rahmat qilsin, ey Umm Sobit.", "note": null},
  {"num": 318, "time": "00:22:20,000 --> 00:22:25,180", "arabic": "اِفْتَقَدْتُكِ حَيْثُ أَنَا بِأَمَسِّ الْحَاجَةِ إِلَيْكِ", "segs": null, "full_uz": "Sizga eng ko'p muhtoj bo'lgan paytimda sizni yo'qotdim.", "note": null},
  {"num": 319, "time": "00:22:25,180 --> 00:22:37,620", "arabic": "لَقَدْ كُنْتِ لِي بِمَثَابَةِ الْأُمِّ الَّتِي تَحِنُّ عَلَيَّ", "segs": null, "full_uz": "Siz men uchun menga mehr ko'rsatuvchi ona kabi edingiz.", "note": null},
  {"num": 320, "time": "00:22:37,620 --> 00:22:43,940", "arabic": "وَالْأُخْتِ الَّتِي تُشَارِكُنِي أَفْرَاحِي وَأَتْرَاحِي", "segs": null, "full_uz": "Va quvonch-qayg'ularimni baham ko'ruvchi singil kabi edingiz.", "note": null},
  {"num": 321, "time": "00:22:43,940 --> 00:22:49,039", "arabic": "لَمْ أَفْتَقِدْ أَحَدًا كَمَا افْتَقَدْتُكِ", "segs": null, "full_uz": "Sizni yo'qotgandek hech kimni yo'qotmaganman.", "note": null},
  {"num": 322, "time": "00:22:51,680 --> 00:22:56,680", "arabic": "مَاذَا أَفْعَلُ وَأَنَا أَرَى شَفِيعًا عَلَى هَذِهِ الْحَالَةِ؟", "segs": null, "full_uz": "Shafi'ni shu holatda ko'rib turib, nima qilay?", "note": null},
  {"num": 324, "time": "00:22:56,680 --> 00:23:04,680", "arabic": "هَلْ أُرَغِّبُهُ فِي الزَّوَاجِ مِنْ أُخْرَى لِتُقِرَّ عَيْنُهُ بِالطِّفْلِ الَّذِي يَنْتَظِرُهُ؟", "segs": null, "full_uz": "Kutayotgan bolasi bilan ko'zi yorishishi uchun uni boshqasiga uylanishga undaymi?", "note": null},
  {"num": 326, "time": "00:23:07,680 --> 00:23:14,680", "arabic": "لَسْتُ أَدْرِي يَا أُمَّ ثَابِتٍ، كَانَ مَا يُخَيِّمُ عَلَيَّ مِنْ حُزْنٍ", "segs": null, "full_uz": "Bilmayman, Umm Sobit. Meni bosib turgan g'am.", "note": null},
  {"num": 328, "time": "00:23:15,680 --> 00:23:20,680", "arabic": "لَيْسَ سِوَى أَوْهَامٍ، لَسْتُ أَدْرِي", "segs": null, "full_uz": "Faqat vahmlardan boshqa narsa emas edi. Bilmayman.", "note": null},
  {"num": 330, "time": "00:23:23,680 --> 00:23:37,640", "arabic": "لِمَاذَا تَجَشَّمَ شَيْخُنَا الشَّافِعِيُّ عَنَاءَ الْمَجِيءِ فِي هَذَا الْوَقْتِ الْمُتَأَخِّرِ مِنَ اللَّيْلِ؟", "segs": null, "full_uz": "Shayximiz ash-Shofi'iy nega kechaning bu kech vaqtida kelish mashaqqatini o'z zimmasiga oldi?", "note": null},
  {"num": 331, "time": "00:23:37,640 --> 00:23:41,900", "arabic": "وَإِنْ كُنْتَ أَحْمَدَ صَنِيعًا فَهَذَا كَرَمٌ مِنْهُ عَلَيْكَ", "segs": null, "full_uz": "Agar bu sizga yaxshilik bo'lsa, bu uning saxovatidir.", "note": null},
  {"num": 332, "time": "00:23:43,360 --> 00:23:47,900", "arabic": "زِيَارَتُكَ عَلَيْنَا وَاجِبٌ يَا أَحْمَدُ، دِينًا وَعِلْمًا وَأُخُوَّةً", "segs": null, "full_uz": "Sizni ziyorat qilish bizga vojib, Ahmad — din, ilm va birodarlik yuzasidan.", "note": null},
  {"num": 333, "time": "00:23:48,460 --> 00:23:51,900", "arabic": "خَيْرًا مِمَّا تَشْكُوهُ؟", "segs": null, "full_uz": "Shikoyat qilayotganingizdan yaxshiroqmi?", "note": null},
  {"num": 334, "time": "00:23:51,900 --> 00:23:58,300", "arabic": "إِنَّهُ دُوَارٌ بَسِيطٌ سَيَذْهَبُ إِنْ شَاءَ اللَّهُ مَعَ آلَامٍ خَفِيفَةٍ فِي الرَّأْسِ", "segs": null, "full_uz": "Bu oddiy bir bosh aylanishi — Alloh xohlasa, boshdagi yengil og'riq bilan birga o'tib ketadi.", "note": null},
  {"num": 336, "time": "00:23:58,300 --> 00:24:02,680", "arabic": "وَغَبَشٍ فِي النَّظَرِ وَالرُّؤْيَةِ، أَجَلْ", "segs": null, "full_uz": "Va ko'rishda bir oz xiralik bilan. Ha.", "note": null},
  {"num": 338, "time": "00:24:02,680 --> 00:24:08,800", "arabic": "مَنْ أَخْبَرَكَ عَزَّكَ اللَّهُ؟ مَا تَشْكُو مِنْهُ هَيِّنٌ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Sizga kim aytdi, Alloh sizni aziz qilsin? Shikoyat qilayotganingiz Alloh xohlasa, yengildir.", "note": null},
  {"num": 340, "time": "00:24:08,800 --> 00:24:16,200", "arabic": "يَبْدُو أَنَّكَ تَعَرَّضْتَ طَوِيلًا لِشَمْسِ بَغْدَادَ الْمُحْرِقَةِ، اَلْحَقِيقَةُ مَا قُلْتَ يَا شَيْخَنَا", "segs": null, "full_uz": "Ko'rinishidan, Bag'dodning kuydiruvchi quyoshiga uzoq vaqt duch kelgansiz. Aytganingiz haqiqat, shayximiz.", "note": null},
  {"num": 342, "time": "00:24:16,200 --> 00:24:21,220", "arabic": "خَرَجْتُ إِلَى الْحُقُولِ فِي عَمَلٍ مَا وَمَكَثْتُ أَكْثَرَ مِمَّا أَمْكُثُ بِالْعَادَةِ", "segs": null, "full_uz": "Bir ish uchun dalalarga chiqdim va odatdagimdan ko'proq qoldim.", "note": null},
  {"num": 344, "time": "00:24:21,220 --> 00:24:28,039", "arabic": "اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، اَلْحَمْدُ لِلَّهِ لَا بَأْسَ لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Har holda alhamdulillah. Alhamdulillah, hech qisi yo'q, hech qisi yo'q, Alloh xohlasa poklovchidir.", "note": "«طَهُورٌ إِنْ شَاءَ اللَّهُ» — kasal ziyoratida aytiladigan, kasallik gunohlarni poklaydi ma'nosidagi ibora."},
  {"num": 347, "time": "00:24:28,039 --> 00:24:35,019", "arabic": "هُوَ اغْفِرْ لِأَخِيكَ تَأَخُّرَهُ فَلَمْ أَعْلَمْ ذَلِكَ إِلَّا قَبْلَ قَلِيلٍ، جَزَاكَ اللَّهُ خَيْرًا", "segs": null, "full_uz": "Akangizning kechikishini kechiring, buni oz oldin bilgan edim, xolos. Alloh sizga yaxshilik bersin.", "note": null},
  {"num": 349, "time": "00:24:35,019 --> 00:24:42,480", "arabic": "لَوْ عَلِمْتُ أَنَّ مَرَضِي سَيُعَجِّلُ بِرُؤْيَتِكَ اللَّيْلَةَ لَخَرَجْتُ كُلَّ يَوْمٍ إِلَى الْحُقُولِ لِتُصِيبَنِي شَمْسُ بَغْدَادَ", "segs": null, "full_uz": "Kasalligim tunda sizni ko'rishimni tezlashtirishini bilganimda, har kuni dalalarga chiqib, Bag'dod quyoshiga chalinardim.", "note": null},
  {"num": 351, "time": "00:24:42,480 --> 00:24:49,000", "arabic": "وَأَعْتَذِرُ مَرَّةً أُخْرَى أَنْ كَلَّفْتُكَ مَشَقَّةَ الْحُضُورِ، لَا عَلَيْكَ يَا ابْنَ أَحْمَدَ لَا عَلَيْكَ", "segs": null, "full_uz": "Yana bir bor uzr so'rayman, sizni kelish mashaqqatiga solganim uchun. Hech qisi yo'q, Ahmadning o'g'li, hech qisi yo'q.", "note": null},
  {"num": 353, "time": "00:24:49,000 --> 00:24:59,000", "arabic": "بَلْ فَزِيَارَةُ الْمَرِيضِ وَاجِبَةٌ عَلَيْنَا وَحَقٌّ لَكَ أَيْضًا، وَقَدْ قُلْتُ فِي ذَلِكَ بَيْتَيْنِ مِنَ الشِّعْرِ أَتَسْمَعُهُمَا؟", "segs": null, "full_uz": "Aksincha, bemorni ziyorat qilish bizga vojib va senga ham haq — shu haqda ikki bayt she'r aytgan edim, eshitasizmi?", "note": null},
  {"num": 355, "time": "00:25:00,000 --> 00:25:02,000", "arabic": "أَجَلْ يَا شَيْخَنَا هَذِهِ آذَانُنَا لَكَ صَاغِيَةٌ", "segs": null, "full_uz": "Ha, shayximiz, quloqlarimiz sizga tikilgan.", "note": null},
  {"num": 356, "time": "00:25:03,000 --> 00:25:10,000", "arabic": "قَالُوا يَزُورُكَ أَحْمَدُ وَتَزُورُهُ، قُلْتُ: اَلْفَضَائِلُ لَا تُغَادِرُ مَنْزِلَهُ", "segs": null, "full_uz": "Dedilarki: «Ahmad seni ziyorat qiladi, sen ham uni ziyorat qilasan». Men dedim: «Fazilatlar uning uyidan chiqib ketmaydi».", "note": null},
  {"num": 358, "time": "00:25:11,000 --> 00:25:19,160", "arabic": "إِنْ زَارَنِي فَلِفَضْلِهِ أَوْ زُرْتُهُ فَلِفَضْلِهِ، فَالْفَضْلُ فِي الْحَالَيْنِ لَهُ", "segs": null, "full_uz": "Agar u meni ziyorat qilsa, o'z fazilatidan; men uni ziyorat qilsam ham, uning fazilatidan — har ikki holda ham fazilat unga tegishlidir.", "note": null},
  {"num": 360, "time": "00:25:19,160 --> 00:25:25,180", "arabic": "لَا فَضَّلَكَ اللَّهُ يَا أَبَا عَبْدِ اللَّهِ، إِنْ كَانَ الْمَرَضُ سَبِيلًا لِقَوْلِكَ الشِّعْرَ فِي أَحْمَدَ", "segs": null, "full_uz": "Alloh sizga bunday fazl qilmasin, Abu Abdulloh — agar kasallik Ahmad haqida she'r aytishingizga sabab bo'lsa.", "note": null},
  {"num": 362, "time": "00:25:25,180 --> 00:25:29,000", "arabic": "فَاعْلَمْ أَنِّي مِنْ غَدٍ مَوْعُوكٌ، فَمَتَى سَتَزُورُنِي يَا شَيْخَنَا؟", "segs": null, "full_uz": "Bilib qo'ying, men ertadan boshlab nogoronman. Meni qachon ziyorat qilasiz, shayximiz?", "note": null},
  {"num": 364, "time": "00:25:29,779 --> 00:25:39,500", "arabic": "جَزَاكَ اللَّهُ خَيْرًا عَلَى حُسْنِ ظَنِّكَ وَرَأْيِكَ فِينَا، وَإِنْ سَمَحْتَ لِي أَنْ أَرُدَّ عَلَيْهِمَا", "segs": null, "full_uz": "Biz haqimizdagi yaxshi gumoningiz uchun Alloh sizga yaxshilik bersin — agar ruxsat bersangiz, o'sha ikki baytga javob beray.", "note": null},
  {"num": 366, "time": "00:25:39,500 --> 00:25:47,079", "arabic": "إِنْ زُرْتَنَا فَبِفَضْلٍ مِنْكَ تَمْنَحُنَا، أَوْ نَحْنُ زُرْنَا فَلِلْفَضْلِ الَّذِي فِيكَ", "segs": null, "full_uz": "Agar bizni ziyorat qilsangiz, bu sizning bergan fazilatingizdir; biz sizni ziyorat qilsak ham, bu sizdagi fazilat uchundir.", "note": null},
  {"num": 368, "time": "00:25:47,079 --> 00:25:54,539", "arabic": "لَا عَدِمْنَا كِلَا الْحَالَيْنِ مِنْكَ وَلَا نَالَ الَّذِي يَتَمَنَّى فِيكَ شَانِيكَ", "segs": null, "full_uz": "Sizdan ikki holni ham yo'qotmaylik, va sizga qarshi biror yomonlik tilagan kishi murodiga yetmasin.", "note": null},
  {"num": 370, "time": "00:25:54,539 --> 00:25:58,740", "arabic": "أَحْسَنْتَ، أَحْسَنْتَ، تَبَارَكَ اللَّهُ فِيكَ يَا ابْنَ أَحْمَدَ", "segs": null, "full_uz": "Barakalla, barakalla — Alloh sizni barakotli qilsin, Ahmadning o'g'li.", "note": null},
  {"num": 372, "time": "00:25:58,740 --> 00:26:05,579", "arabic": "هَذِهِ بِتِلْكَ، إِذَا كَانَ الْأَمْرُ كَذَلِكَ فَقَدْ ضَرَبْتُ صَفْحًا عَنْ مَعِّكَ غَدًا", "segs": null, "full_uz": "Bu — o'shaniki uchun. Bunday ekan, ertaga sizga bo'lgan g'azabimdan voz kechdim.", "note": null},
  {"num": 374, "time": "00:26:05,579 --> 00:26:17,659", "arabic": "أُرِيدُهَا حَرْبًا قَصِيرَةً، حَرْبًا خَاطِفَةً، حَرْبًا تَرْدَعُ مَنْ أَخْلَفَ", "segs": null, "full_uz": "Men uni qisqa jang qilib istayman — chaqmoqday urush, va'daga xiyonat qilganni to'sadigan urush.", "note": null},
  {"num": 377, "time": "00:26:17,659 --> 00:26:24,959", "arabic": "وَتُرْدِي بِمَنْ حَنِثَ وَاسْتَنْكَفَ عَنْ أَمْرِ أَمِيرِ الْمُؤْمِنِينَ، وَنَحْنُ لَهَا يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Va qasamni buzib, Amir al-Mo'minin buyrug'idan bosh tortganni halok qiladigan urush. Biz unga tayyormiz, Amir al-Mo'minin.", "note": null},
  {"num": 379, "time": "00:26:24,959 --> 00:26:30,739", "arabic": "سَتَرَى مِنَّا مَا يَسُرُّكَ وَيُرْضِيكَ عَنْهُ، بِإِذْنِ اللَّهِ تَعَالَى وَهَذَا وَعْدٌ", "segs": null, "full_uz": "Bizdan sizni xursand qiladigan va rozi qiladigan narsani ko'rasiz — Alloh taolo izni bilan, bu va'dadir.", "note": null},
  {"num": 381, "time": "00:26:30,739 --> 00:26:44,380", "arabic": "وَأُرِيدُ لِأَهْلِ خُرَاسَانَ أَنْ يَعْلَمُوا أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْأَمِينَ ابْنَ هَارُونَ الرَّشِيدِ لَا يُمْتَحَنُ فِي صَبْرِهِ", "segs": null, "full_uz": "Xuroson ahli Amir al-Mo'minin al-Amin, Horun ar-Rashidning o'g'li sabrida sinovga tortilmasligini bilishlarini istayman.", "note": null},
  {"num": 384, "time": "00:26:44,380 --> 00:26:53,200", "arabic": "كَمَا امْتُحِنَ مَنْ جَعَلُوا ظَهْرَهُ لَهُمْ مَطِيَّةً، وَلْيَعْلَمِ الْمَأْمُونُ عِلْمًا لَا شَكَّ فِيهِ", "segs": null, "full_uz": "Belini o'zlariga mink qilib olganlar sinovga tortilganidek. Al-Ma'mun shubhasiz bilib qo'ysinki.", "note": null},
  {"num": 386, "time": "00:26:53,200 --> 00:26:59,840", "arabic": "أَنَّ مَا فَعَلَهُ كَانَ جُرْمًا سَيَكُونُ أَوَّلَ مَنْ يَدْفَعُ ثَمَنَهُ", "segs": null, "full_uz": "Uning qilgani jinoyat edi, va uning bahosini birinchi bo'lib o'zi to'laydi.", "note": null},
  {"num": 388, "time": "00:26:59,840 --> 00:27:06,420", "arabic": "أُرِيدُهُ هُنَا مُقَيَّدًا تَحْتَ قَدَمِي، هُوَ مَنْ نَاصَرَهُ وَآزَرَهُ مِنْ أَهْلِ خُرَاسَانَ", "segs": null, "full_uz": "Uni oyoqlarim ostida kishanlangan holda bu yerda ko'rmoqchiman — bu Xuroson ahlidan uni qo'llab-quvvatlagan va yordamlashganlar.", "note": null},
  {"num": 390, "time": "00:27:06,420 --> 00:27:11,759", "arabic": "وَمَا أَهْلُ خُرَاسَانَ يَا مَوْلَايَ؟ إِنَّهُمْ لَنْ يَصْمُدُوا أَمَامَنَا إِلَّا لَيْلَةً وَضُحَاهَا", "segs": null, "full_uz": "Xuroson ahli nima bo'lardi, xo'jayinim? Ular oldimizda bir tun va uning tongidan boshqa bardosh berolmaydi.", "note": null},
  {"num": 392, "time": "00:27:11,759 --> 00:27:21,819", "arabic": "وَمَنْ تَرَوْنَ أَهْلًا لِلْخُرُوجِ عَلَى رَأْسِ الْجُنْدِ؟", "segs": null, "full_uz": "Kimni qo'shin boshida chiqishga munosib deb bilasiz?", "note": null},
  {"num": 394, "time": "00:27:23,259 --> 00:27:29,259", "arabic": "أَرَى إِنْ رَأَى مَوْلَايَ أَنَّ أَنْسَبَ رَجُلٍ لِذَلِكَ هُوَ عَلِيُّ بْنُ عِيسَى بْنِ مَاهَانَ", "segs": null, "full_uz": "Fikrimcha, xo'jayinim shunday ko'rsa, bunga eng mos kishi Ali ibn Iso ibn Mohandir.", "note": null},
  {"num": 395, "time": "00:27:29,259 --> 00:27:35,240", "arabic": "هُوَ كَانَ وَالِيًا عَلَى خُرَاسَانَ فَتْرَةً طَوِيلَةً وَهُوَ أَدْرَى بِدُرُوبِهَا وَشِعَابِهَا", "segs": null, "full_uz": "U uzoq muddat Xurosonga hokim bo'lgan va uning yo'l-yo'lakchalarini yaxshi biladi.", "note": null},
  {"num": 396, "time": "00:27:35,240 --> 00:27:43,359", "arabic": "نِعْمَ الرَّجُلُ ابْنُ مَاهَانَ، إِنَّهُ رَجُلُ الْحُرُوبِ بِلَا مُنَازِعٍ وَهُوَ الْأَنْسَبُ لِهَذِهِ الْمُهِمَّةِ", "segs": null, "full_uz": "Ibn Mohan qanday ajoyib kishi — u urushlar odami, raqibsiz, va bu vazifaga eng munosibi shudir.", "note": null},
  {"num": 399, "time": "00:27:43,359 --> 00:27:54,700", "arabic": "إِذَنْ فَلْيَخْرُجْ عَلَى رَأْسِ الْجُنْدِ وَلْيَأْخُذْ مَعَهُ مَا شَاءَ مِنَ الْعُدَّةِ وَالْعَتَادِ لِيَقْضِيَ اللَّهُ بِهِ أَمْرًا كَانَ مَفْعُولًا", "segs": null, "full_uz": "Unda qo'shin boshida chiqib, o'zi bilan istagan qurol-yarog'ni olib ketsin, toki Alloh u orqali bo'lishi lozim bo'lgan ishni amalga oshirsin.", "note": "«أَمْرًا كَانَ مَفْعُولًا» — Ahzob surasi, 33:37-oyatga ishora."},
  {"num": 402, "time": "00:27:54,700 --> 00:28:06,619", "arabic": "وَإِنْ كُنْتُ أَعْلَمُ تَوَاضُعَكَ الشَّدِيدَ مَعَ مَا أَنْتَ عَلَيْهِ مِنَ الْعِلْمِ بِحَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِقْهِ دَلَالَاتِهِ", "segs": [{"ar": "وَإِنْ كُنْتُ أَعْلَمُ تَوَاضُعَكَ الشَّدِيدَ", "uz": "Sizdagi kuchli tavoze'ni bilsam-da"}, {"ar": "مَعَ مَا أَنْتَ عَلَيْهِ مِنَ الْعِلْمِ بِحَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِقْهِ دَلَالَاتِهِ", "uz": "Rasululloh sollallohu alayhi va sallamning hadisi va uning dalolatlari fiqhidagi ilmingizga qaramay"}], "full_uz": "Rasululloh sollallohu alayhi va sallamning hadisi va uning dalolatlari fiqhidagi ilmingizga qaramay, sizdagi kuchli tavoze'ni bilsam-da.", "note": null},
  {"num": 405, "time": "00:28:06,619 --> 00:28:13,839", "arabic": "وَلَكِنْ لِنَقُلْ أَنَّنِي عَاتِبٌ لِإِغْلَاكَ أَحْيَانًا فِي تَوَاضُعِكَ", "segs": null, "full_uz": "Ammo aytaylik — sizning ba'zan tavoze'da haddan oshib ketishingizdan xafaman.", "note": null},
  {"num": 407, "time": "00:28:13,839 --> 00:28:19,459", "arabic": "وَأَنِّي لَأَحْمَدُ اللَّهَ أَنْ رَأَيْتَنِي أُغْلِي فِي التَّوَاضُعِ لَا فِي الْكِبَرِ يَا أَبَا زَكَرِيَّا", "segs": null, "full_uz": "Meni tavoze'da haddan oshgan holda ko'rganingizga Allohga hamd aytaman, takabburlikda emas, Abu Zakariyo.", "note": null},
  {"num": 409, "time": "00:28:19,459 --> 00:28:24,219", "arabic": "فَلَا تَوَاضُعَ إِلَّا مَنْ أَوْغَلَ فِي مَعْرِفَةِ حَقِيقَةِ نَفْسِهِ", "segs": null, "full_uz": "Chunki faqat o'z nafsining haqiqatini chuqur bilgan kishigina tavoze' qilishga qodir.", "note": null},
  {"num": 410, "time": "00:28:24,219 --> 00:28:33,019", "arabic": "وَلَكِنْ أَرَى أَنَّكَ تُبَالِغُ فِي التَّوَاضُعِ لِلشَّافِعِيِّ، هُوَ وَالْحَقُّ يُقَالُ رَجُلٌ يَعِزُّ مَثِيلُهُ", "segs": null, "full_uz": "Ammo, menimcha, ash-Shofi'iyga bo'lgan tavoze'ingizda ortiqcha ketyapsiz — haqiqatan ham u tengi kam topiladigan kishi.", "note": null},
  {"num": 412, "time": "00:28:33,019 --> 00:28:42,480", "arabic": "وَأَنَا أَرَى أَيْضًا أَنَّكَ لَا تَقِلُّ عَنْهُ عِلْمًا وَفِقْهًا، وَقَدْرُكَ عِنْدَ أَهْلِ بَغْدَادَ فِي الْمَكَانِ الْأَسْمَى", "segs": null, "full_uz": "Men esa sizni ilm va fiqhda undan kam emas deb bilaman — Bag'dod ahli nazdida qadringiz eng yuqori maqomdadir.", "note": null},
  {"num": 414, "time": "00:28:42,480 --> 00:28:52,980", "arabic": "فَلَا يَلِيقُ بِكَ وَبِنَظَرِ أَصْحَابِكَ وَشُيُوخِكَ إِلَيْكَ أَنْ تَتَوَاضَعَ كُلَّ هَذَا التَّوَاضُعِ لِلشَّافِعِيِّ عَلَى الرَّغْمِ مِنْ عِلْمِهِ وَفَضْلِهِ", "segs": [{"ar": "فَلَا يَلِيقُ بِكَ وَبِنَظَرِ أَصْحَابِكَ وَشُيُوخِكَ إِلَيْكَ", "uz": "Do'stlaringiz va shayxlaringizning sizga bo'lgan nazariga munosib emas"}, {"ar": "أَنْ تَتَوَاضَعَ كُلَّ هَذَا التَّوَاضُعِ لِلشَّافِعِيِّ عَلَى الرَّغْمِ مِنْ عِلْمِهِ وَفَضْلِهِ", "uz": "ash-Shofi'iyning ilmi va fazliga qaramay, unga bunday darajada tavoze' qilishingiz"}], "full_uz": "Do'stlaringiz va shayxlaringizning sizga bo'lgan nazariga munosib emas — ash-Shofi'iyning ilmi va fazliga qaramay, unga bunday darajada tavoze' qilishingiz.", "note": null},
  {"num": 417, "time": "00:28:52,980 --> 00:28:57,160", "arabic": "أَعْرِفُ أَنَّ قَلْبَكَ الَّذِي يَتَحَدَّثُ يَا أَبَا زَكَرِيَّا وَلَيْسَ عَقْلَكَ", "segs": null, "full_uz": "Bilaman, gapirayotgan qalbingiz, aqlingiz emas, Abu Zakariyo.", "note": null},
  {"num": 418, "time": "00:28:57,160 --> 00:29:04,660", "arabic": "فَلَا يَحْمِلَنَّكَ حُبُّكَ لِي عَلَى قَوْلِ مَا تَقُولُ مِنْ مِثْلِ شَيْخِنَا الشَّافِعِيِّ فَضْلًا وَعِلْمًا", "segs": null, "full_uz": "Menga bo'lgan muhabbating shayximiz ash-Shofi'iydek fazl va ilm sohibi haqida shu gapni aytishga sabab bo'lmasin.", "note": null},
  {"num": 420, "time": "00:29:04,660 --> 00:29:11,500", "arabic": "وَأَيْنَ ابْنُ حَنْبَلٍ مِنْهُ يَا رَجُلُ؟ وَهَذَا مَا أُسَمِّيهِ إِغْلَاءً فِي التَّوَاضُعِ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Ibn Hanbal undan qayerda turadi, ey odam? Mana buni men tavoze'da haddan oshish deb ataymanki, Ibn Hanbal.", "note": null},
  {"num": 422, "time": "00:29:11,500 --> 00:29:19,800", "arabic": "إِنَّهُ لَيْسَ تَوَاضُعًا يَا ابْنَ مَعِينٍ، إِنَّمَا إِنْزَالُ النَّاسِ مَنَازِلَهُمْ، وَانْقُلْ عَنِّي", "segs": null, "full_uz": "Bu tavoze' emas, Ibn Ma'in — bu odamlarni o'z martabalariga qo'yishdir. Mendan yetkazing.", "note": null},
  {"num": 425, "time": "00:29:19,800 --> 00:29:22,740", "arabic": "لَوْلَا الشَّافِعِيُّ مَا عَرَفْنَا فِقْهَ الْحَدِيثِ", "segs": null, "full_uz": "Ash-Shofi'iy bo'lmaganida, hadis fiqhini bilmagan bo'lardik.", "note": null},
  {"num": 426, "time": "00:29:31,160 --> 00:29:34,920", "arabic": "تُرَى مَنِ الَّذِي غَيَّرَ حَالَكَ يَا شَفِيعُ؟", "segs": null, "full_uz": "Qiziq, holingni kim o'zgartirdi, Shafi'?", "note": null},
  {"num": 427, "time": "00:29:34,920 --> 00:29:47,080", "arabic": "لَمْ تَكُنْ يَوْمًا تَنَامُ وَتَتْرُكُنِي هَكَذَا وَحِيدَةً تُعَانِي مَرَارَةَ الْبُعْدِ وَالْجَفَا", "segs": null, "full_uz": "Ilgari hech qachon meni ayriliq va jafo achchig'ini his qilib, shu tarzda yolg'iz uxlab qoldirmagan eding.", "note": null},
  {"num": 429, "time": "00:29:47,080 --> 00:29:53,200", "arabic": "لَا يُعْقَلُ أَنَّكَ لَمْ تَعُدْ تُحِبُّنِي كَالسَّابِقِ", "segs": null, "full_uz": "Meni endi avvalgidek sevmasliging aqlga sig'maydi.", "note": null},
  {"num": 430, "time": "00:29:53,200 --> 00:29:57,560", "arabic": "لَيْتَكَ تُخْبِرُنِي مَنِ الَّذِي غَيَّرَكَ", "segs": null, "full_uz": "Koshki seni kim o'zgartirganini aytib bersang.", "note": null},
  {"num": 431, "time": "00:30:01,160 --> 00:30:13,960", "arabic": "كَأَنَّكَ لَا تَكْتَرِثُ بِمَا يَفْعَلُهُ الشَّافِعِيُّ مِنْ إِفْسَادٍ لِعُقُولِ النَّاسِ", "segs": null, "full_uz": "Xuddi ash-Shofi'iyning odamlar aqlini buzayotgan ishiga parvo qilmagandeksan.", "note": null},
  {"num": 432, "time": "00:30:13,960 --> 00:30:18,500", "arabic": "اَلشَّافِعِيُّ يُفْسِدُ عُقُولَ النَّاسِ؟ يَا رَجُلُ", "segs": null, "full_uz": "Ash-Shofi'iy odamlar aqlini buzyaptimi? Ey odam.", "note": null},
  {"num": 434, "time": "00:30:18,500 --> 00:30:24,500", "arabic": "لَا تَكُفَّ عَنْ قَوْلِ مَا لَا تَقْتَنِعُ بِهِ، أَحَقًّا تُصَدِّقُ نَفْسَكَ؟", "segs": null, "full_uz": "O'zing ishonmagan narsani aytishdan to'xtamaysan-a. Rostdan o'zingga ishonasanmi?", "note": null},
  {"num": 436, "time": "00:30:25,060 --> 00:30:33,380", "arabic": "أَلَيْسَتْ هَذِهِ هِيَ الْحَقِيقَةُ؟ أَيَّ حَقِيقَةٍ تَقْصِدُ؟", "segs": null, "full_uz": "Bu haqiqat emasmi? Qanday haqiqatni nazarda tutyapsan?", "note": null},
  {"num": 438, "time": "00:30:33,380 --> 00:30:41,859", "arabic": "اَلْحَقِيقَةُ الَّتِي تَرَاهَا أَنْتَ وَصَحْبُكَ الْمُعْتَزِلَةُ، أَنَا أَعْرِفُ أَنَّهُ قَدْ سَاءَكَ مَجْدُ الشَّافِعِيِّ فِي بَغْدَادَ", "segs": null, "full_uz": "Sen va sening Mo'tazila hamrohlaring ko'rgan haqiqat. Bilamanki, ash-Shofi'iyning Bag'doddagi shuhrati seni xafa qilgan.", "note": null},
  {"num": 440, "time": "00:30:41,859 --> 00:30:48,039", "arabic": "وَكَشْفُهُ لِلشَّاذِّ مِنِ اعْتِقَادِكُمْ أَمَامَ النَّاسِ وَانْصِرَافُ النَّاسِ عَنْكُمْ", "segs": null, "full_uz": "Va uning e'tiqodingizdagi g'ayritabiiy narsani odamlar oldida fosh qilishi hamda odamlarning sizdan yuz o'girishi.", "note": null},
  {"num": 441, "time": "00:30:48,039 --> 00:30:56,019", "arabic": "غَرِيبٌ أَمْرُكَ يَا صَاحِبِي، نُخَاطِبُ عَقْلَكَ فَتَثُورُ عَلَيْنَا كَأَنَّكَ تَتَكَلَّمُ عَنْ أَبِي بَكْرٍ الصِّدِّيقِ أَوْ عُمَرَ بْنِ الْخَطَّابِ", "segs": null, "full_uz": "G'aroyib ishing bor, do'stim — aqlingga murojaat qilyapmiz, sen esa go'yo Abu Bakr as-Siddiq yoki Umar ibn al-Xattob haqida gapirayotgandek bizga qarshi qo'zg'olib turibsan.", "note": null},
  {"num": 443, "time": "00:30:56,019 --> 00:31:01,599", "arabic": "ثُمَّ يَمْنَعُكَ كُرْهُكَ لِأَحْمَدَ بْنِ حَنْبَلٍ مِنَ الِاخْتِلَافِ إِلَى الشَّافِعِيِّ", "segs": null, "full_uz": "Yana, Ahmad ibn Hanbalga bo'lgan nafrating seni ash-Shofi'iyga qatnashishdan man qilyapti.", "note": null},
  {"num": 444, "time": "00:31:01,599 --> 00:31:05,900", "arabic": "مَنْ مَنَ الَّذِي انْصَاعَ لَهُ وَهُوَ لَمْ يَنْصَعْ لِعَقْلِهِ؟", "segs": null, "full_uz": "Aqliga bo'ysunmagan kishi kimga bo'ysunibdi?", "note": null},
  {"num": 445, "time": "00:31:05,900 --> 00:31:14,639", "arabic": "أَمَّا بُغْضِي لِأَحْمَدَ وَكُرْهِي لِرُؤْيَةِ مَنْزِلَتِهِ عِنْدَ الشَّافِعِيِّ فَلَمْ يَمْنَعَانِي مِنْ قَوْلِ الْحَقِّ الَّذِي لَا مِرَاءَ فِيهِ", "segs": null, "full_uz": "Ahmadga bo'lgan g'azabim va uning ash-Shofi'iy nazdidagi martabasini ko'rishga bo'lgan nafratim, hech qanday shubha bo'lmagan haqni aytishimga to'sqinlik qilmadi.", "note": null},
  {"num": 447, "time": "00:31:14,639 --> 00:31:20,700", "arabic": "أَنَا لَا أُنْكِرُ لِأَهْلِ الْفَضْلِ فَضْلَهُمْ، أَمَّا مَا بَيْنِي وَبَيْنَ أَحْمَدَ", "segs": null, "full_uz": "Fazl ahlining fazlini inkor etmayman — men bilan Ahmad o'rtasidagi narsaga kelsak.", "note": null},
  {"num": 449, "time": "00:31:20,700 --> 00:31:24,339", "arabic": "فَهُوَ مِمَّا لَنْ يَضُرَّنِي فِي دِينِي إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Bu, Alloh xohlasa, dinimga zarar keltirmaydigan narsadir.", "note": null},
  {"num": 450, "time": "00:31:24,339 --> 00:31:33,659", "arabic": "أَنْتُمْ تَجِدُونَ لِأَنْفُسِكُمُ الذَّرَائِعَ دَائِمًا وَتَلْتَمِسُونَ لَكُمُ الْأَعْذَارَ فِي كُلِّ صَوْبٍ وَنَاحِيَةٍ", "segs": null, "full_uz": "Sizlar o'zlaringizga doim bahonalar topasizlar va har tomondan o'zingizga uzr izlaysizlar.", "note": null},
  {"num": 452, "time": "00:31:33,659 --> 00:31:39,839", "arabic": "أَنْتُمْ؟ مَا الَّذِي تَقْصِدُهُ بِأَنْتُمْ يَا بَدْرُ؟", "segs": null, "full_uz": "Sizlar-a? Sizlar deganda nimani nazarda tutyapsan, Badr?", "note": null},
  {"num": 454, "time": "00:31:39,839 --> 00:32:24,319", "arabic": "أَنْتُمُ الْعَوَامُّ يَا صَدِيقَ بَدْرٍ", "segs": null, "full_uz": "Sizlar — omma, ey Badrning do'sti.", "note": null},
  {"num": 456, "time": "00:32:24,339 --> 00:32:28,639", "arabic": "وَيْحَ أُمَّةٍ تَتَلَهَّى بِقَتْلِ نَفْسِهَا عَنْ قِتَالِ عَدُوِّهَا", "segs": null, "full_uz": "Voy holiga — dushmaniga qarshi jang o'rniga o'z-o'zini o'ldirish bilan ovunayotgan ummatning.", "note": null},
  {"num": 457, "time": "00:32:28,639 --> 00:32:35,639", "arabic": "وَلَهْفِي عَلَى الْإِسْلَامِ الَّذِي يَنْتَقِصُ بِيَدِ أَبْنَائِهِ وَحُكَّامِهِ", "segs": null, "full_uz": "Va o'z farzandlari va hukmdorlarining qo'li bilan kamaytirilayotgan Islomga achinaman.", "note": null},
  {"num": 458, "time": "00:32:35,639 --> 00:32:42,019", "arabic": "لَمْ يَكْفِهِمْ شَحْبُ أَلْسِنَتِهِمْ عَلَى أَنْفُسِهِمْ حَتَّى سَلُّوا سُيُوفَهُمْ", "segs": null, "full_uz": "Bir-birlariga qarshi tillarini zaharlashlari yetmagandek, endi qilichlarini ham sug'urib olishdi.", "note": null},
  {"num": 459, "time": "00:32:42,019 --> 00:32:50,339", "arabic": "إِلَى أَيْنَ وَصَلْتَ يَا مِقْدَادُ؟ مَاذَا أَصَابَكَ يَا مِقْدَادُ؟", "segs": null, "full_uz": "Qayerga yetding, Miqdod? Senga nima bo'ldi, Miqdod?", "note": null},
  {"num": 461, "time": "00:32:50,339 --> 00:32:57,339", "arabic": "إِلَى أَيْنَ تُرِيدِينَ أَخْذَنَا يَا مِهْرَانُ؟ مَاذَا أَصَابَكَ يَا مِهْرَانُ؟", "segs": null, "full_uz": "Bizni qayerga olib borishni istaysan, Mehron? Senga nima bo'ldi, Mehron?", "note": null},
  {"num": 463, "time": "00:32:57,339 --> 00:33:09,339", "arabic": "وَاتْلُ عَلَيْهِمْ نَبَأَ ابْنَيْ آدَمَ بِالْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ الْآخَرِ", "segs": null, "full_uz": "Ularga Odam ikki o'g'lining xabarini rost bilan tilovat qilib ber — ular qurbonlik keltirganlarida, birovnikidan qabul qilindi, ikkinchisinikidan qabul qilinmadi.", "note": "Bu Qur'oni karim, Moida surasi 27-oyatidan iqtibos."},
  {"num": 466, "time": "00:33:09,339 --> 00:33:15,339", "arabic": "هَابِيلُ آخَرُ، وَقَابِيلُ آخَرُ", "segs": null, "full_uz": "Habil boshqa, Qobil esa boshqa.", "note": null},
  {"num": 468, "time": "00:33:15,339 --> 00:33:19,339", "arabic": "هَابِيلُ آخَرُ", "segs": null, "full_uz": "Habil boshqadir.", "note": null},
  {"num": 469, "time": "00:33:19,339 --> 00:33:32,099", "arabic": "هَكَذَا إِذَنْ فَقَدْ أَعْلَنَهَا أَخِي الْأَمِينُ حَرْبًا", "segs": null, "full_uz": "Demak, akam al-Amin buni urush deb e'lon qildi.", "note": null},
  {"num": 470, "time": "00:33:32,099 --> 00:33:37,220", "arabic": "أَجَلْ يَا مَوْلَايَ، وَهَذَا كِتَابٌ مِنْ أَحَدِ عُيُونِنَا فِي بَغْدَادَ", "segs": null, "full_uz": "Ha, xo'jayinim, va bu Bag'doddagi josuslarimizdan birining xati.", "note": null},
  {"num": 471, "time": "00:33:37,220 --> 00:33:45,359", "arabic": "يُخْبِرُنَا أَنَّ الْأَمِينَ قَدْ جَهَّزَ جَيْشًا قِوَامُهُ أَرْبَعُونَ أَلْفَ مُقَاتِلٍ، أَرْبَعُونَ أَلْفَ مُقَاتِلٍ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Al-Amin qirq ming jangchidan iborat qo'shin tayyorlaganini bizga xabar bermoqda. Qirq ming jangchi, Abu al-Abbos!", "note": null},
  {"num": 473, "time": "00:33:45,359 --> 00:33:50,240", "arabic": "إِنَّهُمْ أَعْدَادٌ هَائِلَةٌ لَا أَظُنُّنَا نَسْتَطِيعُ أَنْ نَبْلُغَ نِصْفَهَا", "segs": null, "full_uz": "Bu ulkan sonlar — yarmiga ham yetolmaymiz deb o'ylayman.", "note": null},
  {"num": 474, "time": "00:33:50,240 --> 00:33:58,359", "arabic": "مَوْلَايَ إِنَّ أَهْلَ الْحَقِّ غَالِبُونَ وَإِنْ قَلَّ نَصْرُهُمْ، وَأَهْلُ الْبَاطِلِ مَخْذُولُونَ عَاجِلًا أَمْ آجِلًا", "segs": [{"ar": "مَوْلَايَ إِنَّ أَهْلَ الْحَقِّ غَالِبُونَ وَإِنْ قَلَّ نَصْرُهُمْ", "uz": "Xo'jayinim, haq ahli yordamlari oz bo'lsa ham g'olibdir"}, {"ar": "وَأَهْلُ الْبَاطِلِ مَخْذُولُونَ عَاجِلًا أَمْ آجِلًا", "uz": "botil ahli esa erta-kech xor bo'ladi"}], "full_uz": "Xo'jayinim, haq ahli yordamlari oz bo'lsa ham g'olibdir, botil ahli esa erta-kech xor bo'ladi.", "note": null},
  {"num": 476, "time": "00:33:59,119 --> 00:34:04,679", "arabic": "نَحْنُ عَلَى الْحَقِّ إِنْ شَاءَ اللَّهُ، هُمْ بَغَوْا عَلَيْنَا وَنَكَثُوا الْعُهُودَ وَالْمَوَاثِيقَ", "segs": null, "full_uz": "Biz, Alloh xohlasa, haq tarafdamiz — ular bizga zulm qildilar va ahdlar hamda ahdnomalarni buzdilar.", "note": null},
  {"num": 478, "time": "00:34:04,679 --> 00:34:12,440", "arabic": "سَنَخْرُجُ إِلَيْهِمْ مَهْمَا كَانَ عَدَدُنَا قَلِيلًا مُتَسَلِّحِينَ بِإِيمَانِنَا، فَإِمَّا أَنْ نَعِيشَ عِيشَةَ الْأَعِزَّاءِ", "segs": [{"ar": "سَنَخْرُجُ إِلَيْهِمْ مَهْمَا كَانَ عَدَدُنَا قَلِيلًا مُتَسَلِّحِينَ بِإِيمَانِنَا", "uz": "Sonimiz qancha oz bo'lsa ham, imonimiz bilan qurollanib ularga qarshi chiqamiz"}, {"ar": "فَإِمَّا أَنْ نَعِيشَ عِيشَةَ الْأَعِزَّاءِ", "uz": "yo azizlar hayotini yashaymiz"}], "full_uz": "Sonimiz qancha oz bo'lsa ham, imonimiz bilan qurollanib ularga qarshi chiqamiz — yo azizlar hayotini yashaymiz.", "note": null},
  {"num": 481, "time": "00:34:12,440 --> 00:34:14,980", "arabic": "وَأَمَّا أَنْ نَمُوتَ مَوْتَ الْكِرَامِ", "segs": null, "full_uz": "Yoki mardlar o'limi bilan o'lamiz.", "note": null},
  {"num": 482, "time": "00:34:15,360 --> 00:34:27,160", "arabic": "مَنِ الَّذِي خَرَجَ عَلَى رَأْسِ جُنْدِ أَهْلِ بَغْدَادَ؟ عَلِيُّ بْنُ عِيسَى بْنِ مَاهَانَ", "segs": null, "full_uz": "Bag'dod ahli qo'shini boshida kim chiqdi? Ali ibn Iso ibn Mohan.", "note": null},
  {"num": 484, "time": "00:34:27,160 --> 00:34:32,320", "arabic": "ذَلِكَ الشَّيْخُ الْمُحَنَّكُ", "segs": null, "full_uz": "O'sha tajribali qariya.", "note": null},
  {"num": 485, "time": "00:34:32,320 --> 00:34:40,860", "arabic": "إِنَّهُ فَارِسٌ لَا يُشَقُّ لَهُ غُبَارٌ، سَيَخْرُجُ لَهُ مَنْ يَفُلُّ حَدَّهُ", "segs": null, "full_uz": "U — tengsiz otliq suvoriy. Unga qarshi uning zug'urini singdiruvchi bir kishi chiqadi.", "note": null},
  {"num": 487, "time": "00:34:40,860 --> 00:34:46,280", "arabic": "وَيَكْسِرُ شَوْكَتَهُ، مَنْ تَقْصِدُ؟", "segs": null, "full_uz": "Va uning shiddatini sindiradi. Kimni nazarda tutyapsan?", "note": null},
  {"num": 489, "time": "00:34:46,280 --> 00:35:04,519", "arabic": "اَلطَّاهِرُ بْنُ الْحُسَيْنِ يَا مَوْلَايَ", "segs": null, "full_uz": "At-Tohir ibn al-Husayn, xo'jayinim.", "note": null},
  {"num": 491, "time": "00:35:04,519 --> 00:35:07,840", "arabic": "هَذِهِ الْحَرْبُ لَيْسَ لَهَا إِلَّا طَاهِرُ بْنُ الْحُسَيْنِ", "segs": null, "full_uz": "Bu urushga faqat Tohir ibn al-Husayn loyiqdir.", "note": null},
  {"num": 492, "time": "00:35:07,840 --> 00:35:31,640", "arabic": "مَا بِكِ يَا فَوْزُ؟ أَعْلَمُ أَنَّهُ مِنْ حَقِّكِ أَنْ يَكُونَ لَكِ وَلَدٌ يَحْمِلُ اسْمَكِ", "segs": null, "full_uz": "Senga nima bo'ldi, Favz? Bilaman — ismingni davom ettiruvchi farzand bo'lishi senga haqli narsa.", "note": null},
  {"num": 494, "time": "00:35:35,260 --> 00:35:38,080", "arabic": "مَا بِكِ؟ لِمَاذَا تَضْحَكِينَ؟", "segs": null, "full_uz": "Senga nima bo'ldi? Nega kulyapsan?", "note": null},
  {"num": 496, "time": "00:35:38,080 --> 00:35:47,840", "arabic": "أَيْنَ ذَهَبَ ظَنُّ السُّوءِ بِكِ يَا فَوْزُ؟ أَتَحْسَبُونَنِي غَافِلَةً عَمَّا يُكَدِّرُكَ", "segs": null, "full_uz": "Sendagi yomon gumon qayerga ketdi, Favz? Meni seni bezovta qilayotgan narsadan g'ofil deb o'ylaysanmi?", "note": null},
  {"num": 498, "time": "00:35:47,840 --> 00:35:53,800", "arabic": "أَنْتَ وَاهِمَةٌ يَا زَوْجِي، فَقَدْ خَانَكِ حَدْسُكِ هَذِهِ الْمَرَّةَ", "segs": null, "full_uz": "Xato o'ylayapsan, erim — bu safar sezgingiz sizga xiyonat qilibdi.", "note": null},
  {"num": 500, "time": "00:35:53,800 --> 00:35:59,700", "arabic": "وَانْتَصَرَتْ غَيْرَةُ الْمَرْأَةِ فِيكِ عَلَى فِطْنَتِهَا، دَعِينِي أُكْمِلْ", "segs": null, "full_uz": "Ayoldagi rashk aql-farosatdan ustun kelibdi. Menga davom ettirishga imkon ber.", "note": null},
  {"num": 502, "time": "00:35:59,700 --> 00:36:08,199", "arabic": "هَذَا الْأَمْرُ الَّذِي تَتَحَدَّثِينَ عَنْهُ مَعْقُودٌ بِمَشِيئَةِ اللَّهِ، لِمَاذَا الْعَجَلَةُ؟", "segs": null, "full_uz": "Siz gapirayotgan bu ish Allohning irodasiga bog'liqdir — shoshilish nimaga kerak?", "note": null},
  {"num": 504, "time": "00:36:08,199 --> 00:36:14,159", "arabic": "مَا زِلْنَا فِي مُقْتَبَلِ الْعُمُرِ، اَلْحَمْدُ لِلَّهِ أَنْ خَابَ ظَنِّي فِيمَا رَأَيْتُ", "segs": null, "full_uz": "Hali umrimizning boshidamiz — o'zim ko'rgan narsada gumonim yolg'on chiqqani uchun alhamdulillah.", "note": null},
  {"num": 506, "time": "00:36:14,159 --> 00:36:20,139", "arabic": "وَحَمْدُ اللَّهِ أَنَّ شَفِيعًا عَلَى عَهْدِهِ كَمَا عَرَفْتُ، وَلَكِنْ قُلْ لِي", "segs": null, "full_uz": "Va Shafi' bilganimdek o'z ahdida ekaniga alhamdulillah. Ammo ayting.", "note": null},
  {"num": 508, "time": "00:36:20,139 --> 00:36:24,440", "arabic": "لِمَاذَا أَنْتَ مُنْذُ مُدَّةٍ جَهْمُ الْوَجْهِ سَيِّئُ الْمِزَاجِ؟", "segs": null, "full_uz": "Nega bir muddatdan beri yuzingiz tund va kayfiyatingiz yomon?", "note": null},
  {"num": 509, "time": "00:36:27,139 --> 00:36:32,079", "arabic": "يُؤَرِّقُنِي هَذَا الْخِلَافُ الَّذِي بَدَأَتْ تَضْطَرِمُ نَارُهُ بَيْنَ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ وَأَخِيهِ الْمَأْمُونِ", "segs": [{"ar": "يُؤَرِّقُنِي هَذَا الْخِلَافُ الَّذِي بَدَأَتْ تَضْطَرِمُ نَارُهُ", "uz": "Olovi kuchayib borayotgan bu nizo meni uyqusiz qoldiryapti"}, {"ar": "بَيْنَ أَمِيرِ الْمُؤْمِنِينَ الْأَمِينِ وَأَخِيهِ الْمَأْمُونِ", "uz": "Amir al-Mo'minin al-Amin va ukasi al-Ma'mun o'rtasida"}], "full_uz": "Amir al-Mo'minin al-Amin va ukasi al-Ma'mun o'rtasida olovi kuchayib borayotgan bu nizo meni uyqusiz qoldiryapti.", "note": null},
  {"num": 511, "time": "00:36:32,079 --> 00:36:37,019", "arabic": "فَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، كُلُّ مَا اسْتَطَعْتُ أَنْ أَفْعَلَهُ", "segs": null, "full_uz": "La havla va la quvvata illa billah. Qila olgan yagona narsam.", "note": null},
  {"num": 513, "time": "00:36:37,019 --> 00:36:41,960", "arabic": "هُوَ أَنْ لَا أَتَعَبَّأَ لِلْحَرْبِ، لَا أُحِبُّ أَنْ أَقْتُلَ مُسْلِمًا بِسَيْفِي يَا فَوْزُ", "segs": null, "full_uz": "Urushga saflanmaslikdir — qilichim bilan bir musulmonni o'ldirishni istamayman, Favz.", "note": null},
  {"num": 515, "time": "00:36:41,960 --> 00:36:47,639", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "La havla va la quvvata illa billah.", "note": null},
  {"num": 516, "time": "00:36:47,639 --> 00:36:53,480", "arabic": "مَا أَرَاكَ إِلَّا مَفْتُونًا بِالشَّافِعِيِّ هَذَا يَا ابْنَ أَكْثَمَ، اَلْحَقُّ أَنِّي لَا أَعْرِفُ الرَّجُلَ", "segs": null, "full_uz": "Sen bu ash-Shofi'iyga oshufta bo'lganga o'xshaysan, Ibn Aksam. Haqiqatda, men bu kishini tanimayman.", "note": null},
  {"num": 518, "time": "00:36:53,480 --> 00:37:00,719", "arabic": "وَلَكِنَّنِي سَمِعْتُ حَدِيثَ الْعُلَمَاءِ فِيهِ وَاطَّلَعْتُ عَلَى بَعْضِ آرَائِهِ فَرَأَيْتُ أَنَّهُ عَالِمٌ قَرِيعُ قَوْمِهِ", "segs": null, "full_uz": "Ammo olimlarning uning haqidagi gapini eshitdim va ba'zi fikrlarini o'rgandim — u o'z qavmining sara olimi ekanini ko'rdim.", "note": "قَرِيعُ قَوْمِهِ — o'z qavmining eng peshqadam, sara kishisi ma'nosidagi ibora."},
  {"num": 521, "time": "00:37:00,719 --> 00:37:10,959", "arabic": "ثُمَّ مَنْ قَالَ إِنَّ الرَّجُلَ يَسْتَقْوِي عَلَيْكُمْ بِالسُّلْطَانِ؟ هَلِ السُّلْطَانُ هُوَ مَنْ أَجْبَرَ النَّاسَ وَالْعُلَمَاءَ عَلَى لُزُومِهِ؟", "segs": null, "full_uz": "Yana, u sizlar ustidan sulton bilan kuchlanyapti degan kim? Sulton odamlar va olimlarni unga ergashishga majburladimi?", "note": null},
  {"num": 523, "time": "00:37:10,959 --> 00:37:20,480", "arabic": "سَيَأْتِي يَوْمٌ تَعْرِفُ فِيهِ أَنْتَ وَغَيْرُكَ أَنَّ ذَلِكَ لَمْ يَكُنْ إِلَّا وَعْكَةً عَابِرَةً فِي جَسَدِ الْأُمَّةِ، وَأَنَّكُمْ كُنْتُمْ مَخْدُوعِينَ فِيهِ", "segs": [{"ar": "سَيَأْتِي يَوْمٌ تَعْرِفُ فِيهِ أَنْتَ وَغَيْرُكَ", "uz": "Bir kun kelib, sen va boshqalar bilib olasiz"}, {"ar": "أَنَّ ذَلِكَ لَمْ يَكُنْ إِلَّا وَعْكَةً عَابِرَةً فِي جَسَدِ الْأُمَّةِ", "uz": "bu ummat tanidagi vaqtinchalik kasallik bo'lganini"}, {"ar": "وَأَنَّكُمْ كُنْتُمْ مَخْدُوعِينَ فِيهِ", "uz": "va bunda aldangan ekanligingizni"}], "full_uz": "Bir kun kelib, sen va boshqalar bunday ummat tanidagi vaqtinchalik kasallik bo'lganini va bunda aldangan ekanligingizni bilib olasiz.", "note": null},
  {"num": 526, "time": "00:37:20,480 --> 00:37:24,539", "arabic": "وَأَنَا فِي انْتِظَارِ ذَلِكَ الْيَوْمِ وَأَرْجُو أَلَّا يَتَأَخَّرَ", "segs": null, "full_uz": "Men o'sha kunni kutmoqdaman va kechikmasligini umid qilaman.", "note": null},
  {"num": 527, "time": "00:37:24,539 --> 00:37:38,019", "arabic": "أَلَمْ أَقُلْ لَكَ يَا أَخِي؟", "segs": null, "full_uz": "Senga aytmaganmidim, akajon?", "note": null},
  {"num": 528, "time": "00:37:38,019 --> 00:37:43,039", "arabic": "إِنَّهَا أَوْهَامُكَ فَحَسْبُ، اَلرَّجُلُ يُفَكِّرُ فِي الْمَشْرِقِ وَالْمَغْرِبِ", "segs": null, "full_uz": "Bu faqat vahmlaring, xolos — u odam mashriq va mag'ribni o'ylaydi.", "note": null},
  {"num": 530, "time": "00:37:43,039 --> 00:37:49,119", "arabic": "وَأَنْتَ لَا تُفَكِّرِينَ إِلَّا تَحْتَ قَدَمَيْكِ، لَعَلَّ شَفِيعًا عَلَى حَقٍّ", "segs": null, "full_uz": "Sen esa faqat oyog'ing ostinigina o'ylaysan. Balki Shafi' haqdir.", "note": null},
  {"num": 532, "time": "00:37:49,119 --> 00:37:54,519", "arabic": "اِنْتَصَرَتْ غَيْرَةُ الْمَرْأَةِ فِيَّ عَلَى فِطْنَتِي فَأَخَذَتْنِي ظُنُونٌ يَمْنَةً وَيَسْرَةً", "segs": null, "full_uz": "Mendagi ayol rashki farosatimdan ustun kelib, meni har tarafga sudragan gumonlar bosdi.", "note": null},
  {"num": 534, "time": "00:37:54,519 --> 00:38:00,440", "arabic": "ذَلِكَ لِأَنَّكِ تُحِبِّينَهُ يَا زَوْجَةَ شَفِيعٍ، أَجَلْ وَاللَّهِ", "segs": null, "full_uz": "Bu — uni sevganingdan, ey Shafi'ning xotini. Ha, Alloh haqi.", "note": null},
  {"num": 536, "time": "00:38:00,440 --> 00:38:06,239", "arabic": "وَهَلْ يَبْقَى غَيْرُ الْحُبِّ بَيْنَ الرَّجُلِ وَزَوْجِهِ؟ حُبِّي لَهُ أَشَدُّ مِنْ حُبِّي لِنَفْسِي", "segs": null, "full_uz": "Erkak va xotini o'rtasida sevgidan boshqa narsa qolarmi? Unga bo'lgan sevgim o'z-o'zimga bo'lgan sevgimdan ham kuchliroq.", "note": null},
  {"num": 538, "time": "00:38:06,239 --> 00:38:16,480", "arabic": "لَقَدْ عَوَّضَنِي عَنْ فَقْدِ أَهْلِي وَغُرْبَتِي وَعَنْ كُلِّ سِنِينِ الْعَذَابِ وَالْحِرْمَانِ", "segs": null, "full_uz": "U oilamdan ayrilganim va g'aribligim, azob va mahrumlik yillarining o'rnini to'ldirdi.", "note": null},
  {"num": 541, "time": "00:38:16,480 --> 00:38:18,899", "arabic": "فَجَزَاهُ اللَّهُ خَيْرًا", "segs": null, "full_uz": "Alloh unga yaxshilik bersin.", "note": null},
  {"num": 542, "time": "00:38:18,900 --> 00:38:25,660", "arabic": "مُصِيبَةٌ أَنْشَبَتْ أَظْفَارَهَا فِي الْإِسْلَامِ وَالْمُسْلِمِينَ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Bu — Islom va musulmonlarga tirnog'ini botirgan bir musibat, Abu Abdulloh.", "note": null},
  {"num": 543, "time": "00:38:25,660 --> 00:38:31,160", "arabic": "هَذَا مَا لَمْ نَحْسُبْ حِسَابَهَا، بَلْ هَذَا مَا كُنَّا نَخْشَاهُ مِنْ قَبْلُ يَا أَحْمَدُ", "segs": null, "full_uz": "Buni hisobga olmagan edik. Yo'q, bu ilgari qo'rqib turgan narsamiz edi, Ahmad.", "note": null},
  {"num": 545, "time": "00:38:31,160 --> 00:38:36,760", "arabic": "سَأَلَنِي الرَّشِيدُ ذَاتَ مَرَّةٍ عَنْ ذَلِكَ فَنَقَلْتُ إِلَيْهِ مَخَاوِفِي", "segs": null, "full_uz": "Ar-Rashid bir marta bu haqda mendan so'ragan edi, men unga xavotirlarimni yetkazgan edim.", "note": null},
  {"num": 547, "time": "00:38:36,760 --> 00:38:45,079", "arabic": "لَكِنَّهُ ظَنَّ أَنَّ كِتَابَةَ الْعُهُودِ وَالْمَوَاثِيقِ بَيْنَ الْأَبْنَاءِ سَتَمْنَعُ قَدَرًا مَحْتُومًا وَقَضَاءً مَرْسُومًا", "segs": null, "full_uz": "Ammo u o'g'illar o'rtasida ahd va ahdnomalar yozish, muqarrar taqdir va belgilangan qazoni to'sadi deb o'ylagan edi.", "note": null},
  {"num": 549, "time": "00:38:45,079 --> 00:38:50,599", "arabic": "وَهَا هُمَا قَدْ بَلَغَا مَا لَا يَرْضَاهُ اللَّهُ وَالرَّسُولُ", "segs": null, "full_uz": "Mana ular Alloh va Rasul rozi bo'lmaydigan darajaga yetishdi.", "note": null},
  {"num": 550, "time": "00:38:50,599 --> 00:38:57,840", "arabic": "يَضْرِبُ الْإِخْوَةُ رِقَابَ بَعْضٍ فِي مَعْرَكَةٍ يَقُولُ فِيهَا الْجَمِيعُ اللَّهُ أَكْبَرُ", "segs": null, "full_uz": "Barchasi «Allohu akbar» deb aytadigan jangda birodarlar bir-birlarining bo'ynini kesmoqda.", "note": null},
  {"num": 551, "time": "00:38:57,840 --> 00:39:04,380", "arabic": "اَللَّهُ أَكْبَرُ عَلَى كُلِّ مَنْ طَغَى وَتَجَبَّرَ، أَإِلَى هَذَا الْحَدِّ وَصَلْنَا يَا أَبَا عَبْدِ اللَّهِ؟", "segs": null, "full_uz": "Alloh har bir tug'yon qilib, o'zini yuqori tutgan kimsadan buyukroqdir. Shu darajaga yetdikmi, Abu Abdulloh?", "note": null},
  {"num": 553, "time": "00:39:04,380 --> 00:39:12,559", "arabic": "وَأَكْثَرَ وَأَكْثَرَ، فَقَدِ اسْتَبَدَّ بِكِلَا الرَّجُلَيْنِ بِطَانَةُ سُوءٍ تُزَيِّنُ لَهُ الْفَتْكَ بِأَخِيهِ", "segs": null, "full_uz": "Undan ham ko'proq — ikkala kishini ham o'ziga akasini o'ldirishni chiroyli ko'rsatuvchi yovuz maslahatchilar egallab olgan.", "note": "بِطَانَةُ سُوء — hukmdorga yaqin bo'lib, yomon fikr beruvchi maslahatchilar, Qur'onda ham ishlatilgan ibora (Oli Imron, 3:118)."},
  {"num": 555, "time": "00:39:12,559 --> 00:39:20,579", "arabic": "اَلْفَتْكُ بِأَخِيهِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Akasini o'ldirish. La havla va la quvvata illa billah, la havla va la quvvata illa billah.", "note": null},
  {"num": 558, "time": "00:39:20,579 --> 00:39:25,360", "arabic": "بَرْدًا وَسَلَامًا يَا رَبِّ، بَرْدًا وَسَلَامًا", "segs": null, "full_uz": "Salqin va salomat qilgin, Rabbim — salqin va salomat.", "note": "«بَرْدًا وَسَلَامًا» — Anbiyo surasi, 21:69-oyatga ishora, Ibrohim uchun olov salqin bo'lgani."},
  {"num": 560, "time": "00:39:44,380 --> 00:39:51,240", "arabic": "حَسَّنَ اللَّهُ لِدُنْيَانَا، حَسَّنَ اللَّهُ لِدِينِنَا", "segs": null, "full_uz": "Alloh dunyomizni yaxshi qilsin, Alloh dinimizni yaxshi qilsin.", "note": null},
  {"num": 562, "time": "00:39:51,240 --> 00:40:01,099", "arabic": "حَسَّنَ اللَّهُ الْكَرِيمُ لِمَا أَهَمَّنَا، حَسَّنَ اللَّهُ الْحَكِيمُ لِمَنْ بَغَى عَلَيْنَا", "segs": null, "full_uz": "Karim Alloh bizni tashvishga solgan narsani yaxshi qilsin, Hakim Alloh bizga zulm qilganni yaxshi qilsin.", "note": null},
  {"num": 564, "time": "00:40:01,099 --> 00:40:09,920", "arabic": "حَسَّنَ اللَّهُ الشَّدِيدُ لِمَنْ كَادَنَا بِسُوءٍ، يَا مُغِيثُ أَغِثْنَا يَا اللَّهُ", "segs": null, "full_uz": "Shadid Alloh bizga yomonlik bilan fitna qilganni yaxshi qilsin — ey Mug'is, bizga madad ber, ey Alloh.", "note": null},
  {"num": 566, "time": "00:40:14,380 --> 00:40:21,820", "arabic": "أُرِيدُ مِنْكَ يَا أَبَا عَبْدِ اللَّهِ أَنْ تَجِدَ مَنْ تَرْضَاهُ مِنْ عُلَمَاءِ بَغْدَادَ وَفُقَهَائِهَا", "segs": null, "full_uz": "Sendan istaymanki, Abu Abdulloh, Bag'dod olim va fuqaholaridan o'zing rozi bo'ladigan birini toping.", "note": null},
  {"num": 567, "time": "00:40:21,820 --> 00:40:27,760", "arabic": "رَجُلًا فَقِيهًا مُتَّبِعًا لَا مُبْتَدِعًا يَتَوَلَّى الْقَضَاءَ فِي الْيَمَنِ", "segs": null, "full_uz": "Yamanda qozilikni egallaydigan, sunnatga ergashuvchi, bid'atchi bo'lmagan bir faqih kishini.", "note": null},
  {"num": 568, "time": "00:40:27,760 --> 00:40:36,820", "arabic": "لَدَيَّ رَجُلٌ لَوْ رَضِيَ بِذَلِكَ فَنِعْمَ الْفَقِيهُ وَالْعَالِمُ، وَهَلْ سَمِعَ بِهِ أَمِيرُ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Menda shunday bir kishi bor — agar rozi bo'lsa, u qanday ajoyib faqih va olim. Amir al-Mo'minin uni eshitganmi?", "note": null},
  {"num": 570, "time": "00:40:38,640 --> 00:40:45,500", "arabic": "اِسْمُهُ أَحْمَدُ بْنُ حَنْبَلٍ الشَّيْبَانِيُّ، لَمْ أَسْمَعْ بِهِ مِنْ قَبْلُ", "segs": null, "full_uz": "Ismi Ahmad ibn Hanbal ash-Shayboniy. Ilgari eshitmagan edim.", "note": null},
  {"num": 572, "time": "00:40:45,500 --> 00:40:55,900", "arabic": "اَلتَّوَاضُعُ زِينَةُ أَهْلِ الْعِلْمِ وَتَاجٌ فَوْقَ رُءُوسِهِمْ يَا أَمِيرَ الْمُؤْمِنِينَ، وَهُوَ شَابٌّ مُتَوَاضِعٌ يَكْرَهُ الرِّئَاسَةَ وَالظُّهُورَ", "segs": [{"ar": "اَلتَّوَاضُعُ زِينَةُ أَهْلِ الْعِلْمِ وَتَاجٌ فَوْقَ رُءُوسِهِمْ يَا أَمِيرَ الْمُؤْمِنِينَ", "uz": "Tavoze' ilm ahlining ziynati va boshlari ustidagi tojidir, Amir al-Mo'minin"}, {"ar": "وَهُوَ شَابٌّ مُتَوَاضِعٌ يَكْرَهُ الرِّئَاسَةَ وَالظُّهُورَ", "uz": "u boshchilik va ko'zga tashlanishni yomon ko'radigan kamtar yigit"}], "full_uz": "Tavoze' ilm ahlining ziynati va boshlari ustidagi tojidir, Amir al-Mo'minin — u boshchilik va ko'zga tashlanishni yomon ko'radigan kamtar yigit.", "note": null},
  {"num": 574, "time": "00:40:55,900 --> 00:41:04,539", "arabic": "أَنْضَى عُمْرَهُ فِي طَلَبِ الْعِلْمِ وَالْفِقْهِ فِي الدِّينِ، وَهُوَ أَيْضًا مُبَرِّزٌ فِي الْحَدِيثِ وَعُلُومِهِ", "segs": null, "full_uz": "Umrini ilm va dindagi fiqh talabiga sarflagan — u hadis va uning ilmlarida ham peshqadamdir.", "note": null},
  {"num": 576, "time": "00:41:04,539 --> 00:41:10,780", "arabic": "إِنَّهُ شَابٌّ عَابِدٌ زَاهِدٌ، لَا أُزَكِّيهِ عَلَى اللَّهِ", "segs": null, "full_uz": "U ibodatga berilgan, zohid yigit — uni Alloh oldida poklamayman.", "note": null},
  {"num": 578, "time": "00:41:10,780 --> 00:41:18,120", "arabic": "وَلَا أَحْسَبُ أَنَّ ثَمَّ أَجْدَرَ مِنْهُ إِذَنْ نَطْلُبُ مِنْهُ ذَلِكَ", "segs": null, "full_uz": "Va undan munosibrog'i bor deb hisoblamayman. Unda undan buni so'raymiz.", "note": null},
  {"num": 580, "time": "00:41:18,120 --> 00:41:23,580", "arabic": "فَإِنْ رَضِيَ فَأْتِ بِهِ مَعَكَ إِلَيْنَا حَتَّى نَرَاهُ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Agar rozi bo'lsa, uni o'zing bilan bizga olib kel, ko'ray, Abu Abdulloh.", "note": null},
  {"num": 582, "time": "00:41:23,580 --> 00:41:30,420", "arabic": "سَأَفْعَلُ إِنْ شَاءَ اللَّهُ يَا أَمِيرَ الْمُؤْمِنِينَ، سَأَفْعَلُ", "segs": null, "full_uz": "Alloh xohlasa, shunday qilaman, Amir al-Mo'minin. Shunday qilaman.", "note": null},
  {"num": 584, "time": "00:41:30,420 --> 00:41:43,119", "arabic": "تَفَضَّلِ اجْلِسْ، لَقَدْ سَمِعْتُ أَنَّ أَهْلَ بَغْدَادَ أَطْلَقُوا عَلَيْكَ لَقَبًا جَدِيدًا وَسَمَّوْكَ بِنَاصِرِ الْحَدِيثِ", "segs": null, "full_uz": "Marhamat, o'tiring — eshitishimcha, Bag'dod ahli sizga yangi laqab qo'yib, «hadis nosiri» deb atashgan.", "note": null},
  {"num": 586, "time": "00:41:43,119 --> 00:41:50,699", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي أَظْهَرَ رِضَاهُ عَنْ شَافِعِيِّهِ مَحَبَّةً فِي قُلُوبِ النَّاسِ", "segs": null, "full_uz": "O'z Shofi'iysidan roziligini odamlar qalbidagi mehr orqali izhor qilgan Allohga hamd bo'lsin.", "note": null},
  {"num": 587, "time": "00:41:50,699 --> 00:41:57,599", "arabic": "اَلْعِلْمُ حُجَّةٌ عَلَى أَهْلِهِ يَا أَمِيرَ الْمُؤْمِنِينَ، حُجَّةٌ عَلَى أَهْلِهِ", "segs": null, "full_uz": "Ilm o'z ahli uchun hujjatdir, Amir al-Mo'minin — o'z ahli uchun hujjat.", "note": null},
  {"num": 589, "time": "00:41:57,599 --> 00:42:04,039", "arabic": "صَدَقْتَ، صَدَقْتَ يَا ابْنَ إِدْرِيسَ", "segs": null, "full_uz": "To'g'ri aytding, to'g'ri aytding, Ibn Idris.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}